.con-delay, .con-status-pill, .con-tier, .con-days { display: inline-block; padding: 2px 6px; border-radius: 4px; font-size: 11px; line-height: 1.3333; font-weight: 600; background: var(--surface-hover); color: var(--text-secondary); }
.con-status-pill { font-family: var(--desk-font); font-size: 12px; }
.con-delay.crit, .con-status-pill.crit, .con-station.crit { background: rgba(244, 63, 94, 0.15); color: #be123c; }
.con-delay.warn, .con-status-pill.warn, .con-station.warn { background: rgba(245, 158, 11, 0.15); color: #92400e; }
html:not([data-theme="light"]) .con-delay.crit, html:not([data-theme="light"]) .con-status-pill.crit, html:not([data-theme="light"]) .con-station.crit { color: #fb7185; }
html:not([data-theme="light"]) .con-delay.warn, html:not([data-theme="light"]) .con-status-pill.warn, html:not([data-theme="light"]) .con-station.warn { color: #fcd34d; }
.con-station { padding: 0 4px; border-radius: 4px; font-weight: 600; }
.con-tier.critical { background: #e11d48; color: #fff; }
.con-tier.warning { background: #f59e0b; color: #fff; }
.con-tier.advisory { background: #0891b2; color: #fff; }
.con-days.teal { background: rgba(20, 184, 166, 0.15); color: #0f766e; }
.con-days.amber { background: rgba(245, 158, 11, 0.15); color: #92400e; }
.con-days.neutral { background: var(--surface-hover); color: var(--text-secondary); }
.con-res-tabs { display: flex; flex-wrap: wrap; border-bottom: 1px solid var(--border-primary); }
.con-res-tab { display: flex; align-items: center; gap: 6px; padding: 10px 16px; border: 0; border-bottom: 2px solid transparent; background: transparent; font-family: inherit; font-size: 11px; font-weight: 600; color: var(--text-secondary); cursor: pointer; }
.con-res-count { padding: 0 6px; border-radius: 9999px; font-size: 10px; }
.con-res-tab.rose .con-res-count { background: rgba(244, 63, 94, 0.15); color: #e11d48; }
.con-res-tab.amber .con-res-count { background: rgba(245, 158, 11, 0.15); color: #d97706; }
.con-res-tab.emerald .con-res-count { background: rgba(16, 185, 129, 0.15); color: #059669; }
.con-res-tab.rose.active { border-bottom-color: #e11d48; background: rgba(244, 63, 94, 0.08); }
.con-res-tab.amber.active { border-bottom-color: #d97706; background: rgba(245, 158, 11, 0.08); }
.con-res-tab.emerald.active { border-bottom-color: #059669; background: rgba(16, 185, 129, 0.08); }
.con-code-band { display: flex; flex-wrap: wrap; gap: 6px; padding: 6px 8px; border-bottom: 1px solid var(--border-primary); background: color-mix(in srgb, var(--bg-elevated) 60%, transparent); }
.con-checkin-search { box-sizing: border-box; width: 240px; padding: 6px 10px; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--surface-card); font-family: inherit; font-size: 11px; color: var(--text-primary); }

/* ── Controller desk D4b-1 — the case pane (legacy SickCallWorkflowPanel + DutyBlockReservesSection +
 *    ReserveCandidateCard + CandidatesPagerBar; copa-preprod d135f46d) ── */
.case-root { display: flex; min-height: 0; flex: 1; flex-direction: column; overflow: hidden; background: var(--surface-card); }
.case-head { display: flex; min-height: 44px; flex-shrink: 0; align-items: flex-start; justify-content: space-between; gap: 8px; padding: 8px 12px; border-bottom: 1px solid var(--border-primary); }
.case-head-text { min-width: 0; }
.case-title { display: -webkit-box; margin: 0; overflow: hidden; font-size: 14px; line-height: 1.25; font-weight: 600; color: var(--text-primary); -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.case-meta { display: flex; margin-top: 2px; flex-wrap: wrap; align-items: baseline; gap: 2px 8px; font-size: 10px; line-height: 1.4286; color: var(--text-tertiary); }
.case-id { font-family: var(--desk-mono); word-break: break-all; }
