.cand-detail { display: flex; flex-direction: column; gap: 10px; padding: 10px 12px 12px 40px; border-top: 1px solid var(--border-primary); background: var(--bg-secondary); }
.cand-detail-block { display: flex; flex-direction: column; gap: 4px; }
.cand-legality { display: inline-block; width: fit-content; padding: 1px 6px; border-radius: 4px; background: var(--surface-hover); font-size: 11px; line-height: 1.4286; font-weight: 600; color: var(--text-secondary); }
.cand-legality.legal { background: color-mix(in srgb, var(--accent-success) 15%, transparent); color: var(--accent-success); }
.cand-legality.illegal { background: color-mix(in srgb, var(--accent-error) 15%, transparent); color: var(--accent-error); }
.cand-unavailable { font-size: 11px; line-height: 1.4286; color: var(--text-tertiary); }
.case-strip { display: grid; grid-template-columns: repeat(auto-fill, minmax(84px, 1fr)); gap: 4px; }
.case-strip-day { display: flex; flex-direction: column; gap: 1px; padding: 4px 6px; border-radius: 4px; background: var(--surface-hover); font-size: 11px; line-height: 1.4286; color: var(--text-secondary); }
.case-strip-day[data-kind="flight"] { background: color-mix(in srgb, var(--accent-success) 15%, transparent); }
.case-strip-day[data-kind="absence"] { background: color-mix(in srgb, var(--accent-error) 15%, transparent); }
.case-strip-date { font-weight: 600; color: var(--text-primary); }
.case-strip-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-primary); }
.trace-list { display: flex; flex-direction: column; gap: 2px; }
.trace-row { display: grid; align-items: baseline; gap: 8px; grid-template-columns: minmax(0, 1fr) auto 12px; max-width: 420px; }
.trace-rule { overflow: hidden; font-size: 11px; line-height: 1.4286; font-weight: 500; text-overflow: ellipsis; white-space: nowrap; color: var(--text-secondary); }
.trace-value { font-family: var(--desk-mono); font-size: 11px; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.trace-dir { font-size: 10px; color: var(--text-tertiary); }
.trace-empty { margin: 0; font-size: 11px; line-height: 1.4286; color: var(--text-tertiary); }
.ftl-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.ftl-chip { display: flex; width: 72px; flex-direction: column; gap: 3px; }
.ftl-label { font-size: 9px; line-height: 1.4286; font-weight: 600; letter-spacing: 0.02em; color: var(--text-secondary); }
.ftl-bar { display: block; width: 100%; height: 1.5px; overflow: hidden; border-radius: 1px; background: var(--border-primary); }
.ftl-bar-fill { display: block; height: 100%; border-radius: 1px; background: var(--accent-success); }
.ftl-chip.warn .ftl-bar-fill { background: var(--accent-warning); }
.ftl-chip.crit .ftl-bar-fill { background: var(--accent-error); }
.ftl-readout { font-family: var(--desk-mono); font-size: 9px; line-height: 1.4286; font-variant-numeric: tabular-nums; color: var(--text-tertiary); }
.ftl-chip.warn .ftl-readout { color: var(--accent-warning); }
.ftl-chip.crit .ftl-readout { color: var(--accent-error); }

/* ── Controller desk D4b-3 — the panes for the types that are not a shortage ── */
.case-attest { padding: 1px 6px; border-radius: 4px; background: var(--surface-hover); font-size: 10px; line-height: 1.4286; font-weight: 600; color: var(--text-tertiary); }
.case-attest.on { background: color-mix(in srgb, var(--accent-success) 15%, transparent); color: var(--accent-success); }
.case-breach, .case-checkin, .case-fdp { display: flex; flex-direction: column; gap: 6px; padding: 12px 12px 0; }
.case-checkin { flex-flow: row wrap; align-items: flex-end; gap: 16px; }
.case-clock { display: flex; flex-direction: column; gap: 2px; }
.case-clock-value { font-family: var(--desk-mono); font-size: 13px; line-height: 1.4286; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.case-gap-pill { padding: 2px 6px; border-radius: 9999px; font-size: 10px; line-height: 1.4286; font-weight: 600; }
.case-gap-pill.missing, .case-gap-pill.late { background: color-mix(in srgb, var(--accent-warning) 15%, transparent); color: var(--accent-warning); }
.case-gap-pill.manual { background: color-mix(in srgb, var(--accent-success) 15%, transparent); color: var(--accent-success); }
.case-fdp-outcome { margin: 0; font-size: 13px; line-height: 1.4286; font-weight: 600; color: var(--text-primary); }
.case-fdp-note { margin: 0; font-size: 11px; line-height: 1.4286; color: var(--text-tertiary); }

/* ── Controller desk D4c — the Monitor detail modals (legacy DeskMonitorAlertModal's surfaces) ── */
/* Top-anchored, not centred: the bodies fill in as their reads land, and a centred panel jumps on every change of height. */
.dm-overlay { position: fixed; inset: 0; z-index: 200; display: flex; align-items: flex-start; justify-content: center; padding: max(16px, 8vh) 16px 16px; background: var(--bg-overlay); }
.dm-panel { display: flex; box-sizing: border-box; width: 100%; max-height: 85vh; flex-direction: column; overflow: hidden; padding: 24px 12px 24px 24px; border: 1px solid var(--border-primary); border-radius: 12px; background: var(--surface-card); box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25); }
.dm-panel:focus { outline: none; }
.dm-head { display: flex; flex: none; align-items: flex-start; justify-content: space-between; gap: 16px; padding-right: 12px; }
.dm-title { margin: 0; font-size: 16px; line-height: 1.25; font-weight: 600; color: var(--text-primary); }
/* Only the body scrolls, so the title and close stay in view; a thin bar in the theme, not the platform default. */
.dm-body { display: flex; flex-direction: column; gap: 16px; min-height: 0; padding: 12px 12px 0 0; overflow-y: auto; scrollbar-gutter: stable; }
.dm-body::-webkit-scrollbar { width: 6px; }
.dm-body::-webkit-scrollbar-track { background: transparent; }
.dm-body::-webkit-scrollbar-thumb { background: var(--border-primary); border-radius: 3px; }
.dm-body::-webkit-scrollbar-button { display: none; }
@supports not selector(::-webkit-scrollbar) { .dm-body { scrollbar-width: thin; scrollbar-color: var(--border-primary) transparent; } }
.dm-section { display: flex; flex-direction: column; gap: 6px; }
.dm-actions { flex-direction: row; justify-content: flex-end; }
.dm-action { border: 1px solid var(--border-primary); border-radius: 6px; background: transparent; color: var(--text-primary); padding: 6px 14px; font-weight: 600; cursor: pointer; }
.dm-action:hover { background: var(--bg-tertiary, rgba(127, 127, 127, 0.12)); }
.dm-flow { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; font-family: var(--desk-mono); font-size: 11px; font-weight: 600; color: var(--text-primary); }
.dm-metrics { display: flex; flex-wrap: wrap; gap: 16px; padding: 12px; border: 1px solid var(--border-primary); border-radius: 8px; background: color-mix(in srgb, var(--surface-hover) 40%, transparent); }
.dm-metric { display: flex; flex-direction: column; gap: 2px; }
.dm-metric-label { font-size: 11px; line-height: 1.4286; color: var(--text-secondary); }
.dm-metric-value { font-family: var(--desk-mono); font-size: 13px; line-height: 1.4286; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.dm-metric.crit .dm-metric-value { color: var(--accent-error); }
.dm-metric.warn .dm-metric-value { color: var(--accent-warning); }
.dm-legs, .dm-crew { width: 100%; border-collapse: collapse; font-size: 12px; }
.dm-legs th, .dm-crew th { padding: 6px 8px; border-bottom: 1px solid var(--border-primary); font-family: var(--desk-font); font-size: 10px; line-height: 1.3333; font-weight: 600; letter-spacing: 0.05em; text-align: left; text-transform: uppercase; color: var(--text-tertiary); }
.dm-legs td, .dm-crew td { padding: 6px 8px; border-bottom: 1px solid var(--border-primary); font-family: var(--desk-mono); font-size: 11px; line-height: 1.3333; color: var(--text-primary); }
.dm-leg-unresolved td { color: var(--text-tertiary); }
.dm-clocks { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.dm-clock-col { display: flex; flex-direction: column; gap: 4px; }
.dm-clock { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.dm-clock-label { font-size: 11px; line-height: 1.4286; color: var(--text-secondary); }
.dm-clock-value { font-family: var(--desk-mono); font-size: 13px; line-height: 1.4286; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.dm-clock.late .dm-clock-value { color: var(--accent-warning); }
.dm-clock.ontime .dm-clock-value { color: var(--accent-success); }
.dm-delay { display: inline-block; padding: 2px 6px; border-radius: 4px; background: color-mix(in srgb, var(--accent-error) 15%, transparent); font-family: var(--desk-mono); font-size: 13px; font-weight: 600; color: var(--accent-error); }
.dm-delay.warn { background: color-mix(in srgb, var(--accent-warning) 15%, transparent); color: var(--accent-warning); }
.dm-state { margin: 0; font-size: 11px; line-height: 1.4286; color: var(--text-tertiary); }

/* Controller desk D5 — the Timeline table (controller-desk.md §D5 visual spec). Marker colours are THEME
   tokens, not a fixed palette: legacy's raw Tailwind utilities never repaint between light and dark. */
.tl-empty { margin: 0; padding: 24px 0; font-size: 11px; line-height: 1.4286; color: var(--text-tertiary); }
.tl-scroll { min-height: 0; flex: 1; overflow: auto; }
.tl-table { width: 100%; min-width: max-content; border-collapse: collapse; table-layout: fixed; text-align: left; }
.tl-table thead { position: sticky; top: 0; z-index: 1; background: var(--surface-card); }
.tl-th { padding: 8px; white-space: nowrap; font-size: 10px; line-height: 1.3333; font-weight: 600; letter-spacing: 0.05em; text-transform: uppercase; color: var(--text-tertiary); }
.tl-th-pos { text-align: center; }
.tl-th.ends-fixed, .tl-table td.ends-fixed { border-right: 1px solid var(--border-primary); }
.tl-th.ends-group, .tl-table td.ends-group { border-right: 1px solid color-mix(in srgb, var(--border-primary) 50%, transparent); }
.tl-row { border-bottom: 1px solid color-mix(in srgb, var(--border-primary) 40%, transparent); }
.tl-row:hover { background: var(--surface-hover); }
.tl-table td { padding: 8px; white-space: nowrap; font-size: 10px; line-height: 1.4; color: var(--text-primary); }
.tl-bank { font-weight: 700; color: var(--accent-primary); }
.tl-time, .tl-missing { font-variant-numeric: tabular-nums; }
.tl-missing { text-align: center; font-weight: 700; color: var(--text-tertiary); }
.tl-missing.alert { color: var(--accent-error); }
.tl-flight { font-weight: 600; }
.tl-route, .tl-aircraft { color: var(--text-secondary); }
.tl-offset { margin-left: 4px; font-size: 10px; font-weight: 500; font-variant-numeric: tabular-nums; color: var(--accent-error); }
.tl-dir { display: inline-block; padding: 1px 4px; border-radius: 4px; font-size: 9px; font-weight: 700; line-height: 1; text-transform: uppercase; }
.tl-dir[data-dir="departure"] { background: color-mix(in srgb, var(--accent-success) 15%, transparent); color: var(--accent-success); }
.tl-dir[data-dir="arrival"] { background: color-mix(in srgb, var(--accent-info) 15%, transparent); color: var(--accent-info); }
.tl-dir[data-dir="other"] { color: var(--text-tertiary); }
.tl-pos-cell { padding: 8px 16px; text-align: center; color: var(--text-tertiary); }
.tl-marker { display: inline-block; width: 12px; height: 12px; margin: 0 2px; border-radius: 50%; vertical-align: middle; }
.tl-marker[data-state="checkedIn"], .tl-marker[data-state="late"] { background: var(--accent-success); }
.tl-marker[data-state="missing"] { width: 10px; height: 10px; margin-top: 1px; border-radius: 1px; transform: rotate(45deg); background: var(--accent-error); }
.tl-marker[data-state="manual"] { width: auto; height: auto; border-radius: 0; background: none; font-size: 11px; line-height: 1; }
.tl-marker[data-state="manual"]::before { content: "🤝"; }
.tl-marker[data-state="transit"] { width: 12px; height: 12px; border-radius: 0; background: none; transform: rotate(45deg); }
.tl-plane { display: block; width: 12px; height: 12px; fill: var(--accent-info); }
.tl-marker[data-state="deadhead"] { background: var(--text-tertiary); }
.tl-marker[data-state="assignedOnLeg"] { background: var(--accent-violet); }
.tl-board { display: flex; min-height: 0; flex: 1; flex-direction: column; gap: 12px; padding: 12px 16px; }
.tl-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
.tl-search { min-width: 0; flex: 1; box-sizing: border-box; padding: 6px 10px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-input); font-family: inherit; font-size: 12px; color: var(--text-primary); }
.tl-search-field { display: flex; min-width: 160px; flex: 1; align-items: center; gap: 4px; box-sizing: border-box; padding: 0 6px 0 0; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-hover); }
.tl-search-field .tl-search { border: 0; background: transparent; }
.tl-search-clear { border: 0; background: transparent; padding: 0 4px; font-size: 12px; line-height: 1; color: var(--text-tertiary); cursor: pointer; }
.tl-legend { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 16px; padding: 6px 2px; font-size: 10px; color: var(--text-secondary); }
.tl-legend-item { display: inline-flex; align-items: center; gap: 6px; }
.checkin-chip, .checkin-notify, .checkin-replace { display: inline-flex; align-items: center; gap: 4px; margin-right: 4px; border-radius: 6px; padding: 1px 8px; font-size: 10px; font-weight: 600; cursor: pointer; }
.checkin-chip.handshake { border: 0; background: color-mix(in srgb, var(--accent-success) 15%, transparent); color: var(--accent-success); }
.checkin-chip.note { border: 0; background: color-mix(in srgb, var(--accent-warning) 15%, transparent); color: var(--accent-warning); }
.checkin-chip.add, .checkin-replace { border: 1px solid var(--border-primary); background: transparent; color: var(--text-secondary); }
.checkin-notify { border: 0; background: color-mix(in srgb, var(--accent-info) 12%, transparent); color: var(--accent-info); }
.checkin-handshake { display: inline-flex; align-items: center; gap: 2px; margin-left: 6px; font-size: 11px; font-weight: 600; color: var(--accent-success); }
.checkin-switch { position: relative; width: 36px; height: 20px; border-radius: 10px; border: 0; padding: 0; cursor: pointer; background: var(--border-primary); transition: background 0.15s; flex-shrink: 0; }
.checkin-switch.on { background: var(--accent-success); }
.checkin-switch-thumb { position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 50%; background: #fff; transition: left 0.15s; }
.checkin-switch.on .checkin-switch-thumb { left: 18px; }
.checkin-switch:disabled { opacity: 0.5; cursor: not-allowed; }
.checkin-switch-card { display: flex; flex-direction: column; gap: 6px; border-radius: 12px; border: 1px solid var(--border-secondary); background: color-mix(in srgb, var(--surface-hover) 40%, transparent); padding: 10px 12px; margin: 10px 0; }
.checkin-switch-card.on { border-color: color-mix(in srgb, var(--accent-success) 40%, transparent); background: color-mix(in srgb, var(--accent-success) 10%, transparent); }
.checkin-switch-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.checkin-switch-label { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 600; color: var(--text-primary); }
.checkin-switch-hint { font-size: 11px; line-height: 1.4; color: var(--text-tertiary); margin: 0; }
.checkin-added-banner { display: flex; align-items: center; gap: 6px; border-radius: 8px; border: 1px solid color-mix(in srgb, var(--accent-success) 30%, transparent); background: color-mix(in srgb, var(--accent-success) 10%, transparent); color: var(--accent-success); padding: 6px 10px; font-size: 12px; font-weight: 600; margin: 8px 0; }
.checkin-history-label { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-tertiary); margin: 8px 0 6px; }
.checkin-history-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.checkin-history-item { border-radius: 8px; border: 1px solid var(--border-secondary); background: color-mix(in srgb, var(--surface-hover) 40%, transparent); padding: 8px 10px; }
.checkin-history-item p { margin: 0; font-size: 12px; color: var(--text-primary); }
.checkin-history-item .glabel { margin-top: 4px; }
.checkin-submit { display: flex; width: 100%; align-items: center; justify-content: center; gap: 6px; border: 0; border-radius: 8px; padding: 10px 16px; font-size: 13px; font-weight: 700; cursor: pointer; margin-top: 8px; background: var(--surface-hover); color: var(--text-tertiary); }
.checkin-submit.ready { background: var(--accent-primary); color: var(--text-on-accent); cursor: pointer; }
.checkin-submit:disabled { cursor: not-allowed; }
.checkin-textarea { display: block; width: 100%; box-sizing: border-box; border-radius: 8px; border: 1px solid var(--border-secondary); background: var(--surface-hover); padding: 8px 10px; font: inherit; font-size: 13px; color: var(--text-primary); outline: none; resize: vertical; margin-top: 8px; }
.checkin-textarea:focus { border-color: var(--accent-info); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-info) 30%, transparent); }
.checkin-textarea:disabled { opacity: 0.5; }

/* Controller desk D6 ruling BG — below the width five tabs need, the segments keep their icons only. */
.nav-seg-group.compact .nav-seg { gap: 0; padding-inline: 8px; }

/* Controller desk D6 — the Day brief board (controller-desk.md §D6 visual spec). */
.br-state { margin: 0; padding: 24px 16px; font-size: 11px; line-height: 1.4286; color: var(--text-tertiary); }
.br-board { display: flex; min-height: 0; flex: 1; flex-direction: column; gap: 12px; overflow-y: auto; padding: 12px 16px; }
.br-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.br-window { font-family: var(--desk-mono); font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.br-hours { font-size: 10px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text-tertiary); }
.br-export { padding: 6px 10px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); font-family: inherit; font-size: 11px; font-weight: 600; color: var(--text-primary); cursor: pointer; }
.br-export:hover { background: var(--surface-hover); }
.br-sections { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 12px; }
.br-section { display: flex; flex-direction: column; gap: 6px; padding: 12px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); }
.br-section-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.br-title { margin: 0; font-size: 11px; font-weight: 600; color: var(--text-primary); }
.br-count { font-family: var(--desk-mono); font-size: 16px; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.br-section[data-status="failed"] .br-count { color: var(--accent-error); }
.br-section[data-status="absent_by_config"] .br-count { color: var(--text-tertiary); }
.br-reason { margin: 0; font-size: 10px; line-height: 1.4; color: var(--text-tertiary); }
.br-section[data-status="failed"] .br-reason { color: var(--accent-error); }
.br-notes { display: flex; margin: 0; flex-direction: column; gap: 6px; padding: 0; list-style: none; }
.br-note { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px; font-size: 10px; line-height: 1.4; }
.br-note-at { font-family: var(--desk-mono); font-variant-numeric: tabular-nums; color: var(--text-tertiary); }
.br-note-author { font-weight: 600; color: var(--text-secondary); }
.br-note-text { flex: 1; min-width: 0; color: var(--text-primary); }
.br-note-text.redacted { font-style: italic; color: var(--text-tertiary); }

/* Controller desk D6 — the Crew Status board (controller-desk.md §D6 visual spec). */
.cs-state { margin: 0; padding: 24px 16px; font-size: 11px; line-height: 1.4286; color: var(--text-tertiary); }
.cs-board { display: flex; min-height: 0; flex: 1; flex-direction: column; gap: 12px; padding: 12px 16px; }
.cs-pills { display: flex; flex-wrap: wrap; gap: 8px; }
.cs-pill { display: flex; flex-direction: column; align-items: center; padding: 6px 12px; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--surface-card); font-family: inherit; cursor: pointer; }
.cs-pill:hover { background: var(--surface-hover); }
.cs-pill.on { border-color: var(--accent-primary); background: var(--surface-hover); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-primary) 40%, transparent); }
.cs-pill-value { font-size: 16px; font-weight: 700; line-height: 1; font-variant-numeric: tabular-nums; color: var(--text-primary); }
.cs-pill-label { margin-top: 2px; font-size: 10px; text-transform: uppercase; letter-spacing: 0.025em; color: var(--text-tertiary); }
.cs-filters { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.cs-search, .cs-select, .cs-clear { box-sizing: border-box; height: 28px; padding: 0 8px; border: 1px solid var(--border-primary); border-radius: 4px; background: var(--surface-card); font-family: inherit; font-size: 11px; color: var(--text-primary); }
.cs-search { min-width: 0; flex: 1; }
.cs-clear { background: var(--surface-hover); cursor: pointer; }
.cs-scroll { min-height: 0; flex: 1; overflow: auto; }
.cs-table { width: 100%; border-collapse: collapse; text-align: left; }
.cs-table thead { position: sticky; top: 0; z-index: 1; background: var(--bg-elevated); }
.cs-th { padding: 6px 8px; white-space: nowrap; border-bottom: 1px solid var(--border-primary); font-size: 10px; font-weight: 600; letter-spacing: 0.05em; text-transform: uppercase; color: var(--text-tertiary); }
.cs-row { border-bottom: 1px solid var(--border-primary); }
.cs-row:hover { background: var(--surface-hover); }
.cs-table td { padding: 6px 8px; white-space: nowrap; font-size: 11px; color: var(--text-primary); }
.cs-name { font-weight: 500; }
.cs-id, .cs-ops { font-family: var(--desk-mono); font-variant-numeric: tabular-nums; color: var(--text-secondary); }
.cs-duty { display: inline-block; padding: 1px 6px; border-radius: 4px; font-size: 10px; font-weight: 600; background: color-mix(in srgb, var(--accent-info) 15%, transparent); color: var(--accent-info); }
.cs-duty[data-duty="flying"] { background: color-mix(in srgb, var(--accent-primary) 15%, transparent); color: var(--accent-primary); }
.cs-duty[data-duty="reserve"] { background: color-mix(in srgb, var(--accent-violet) 15%, transparent); color: var(--accent-violet); }
.cs-duty[data-duty="rest"] { background: color-mix(in srgb, var(--accent-sky) 15%, transparent); color: var(--accent-sky); }
.cs-slot { margin-left: 4px; font-family: var(--desk-mono); font-size: 10px; color: var(--text-tertiary); }

/* Controller desk D7 — the Notes button and its badge, and the drawer's own body. */
.desk-notes-btn { position: relative; display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); font-family: inherit; font-size: 12px; font-weight: 500; color: var(--text-secondary); cursor: pointer; }
.desk-notes-btn:hover { background: var(--surface-hover); color: var(--text-primary); }
.desk-notes-badge { position: absolute; top: -4px; right: -4px; min-width: 16px; padding: 0 4px; border-radius: 999px; background: var(--accent-error); font-size: 10px; font-weight: 700; line-height: 16px; text-align: center; color: #fff; }
.np-panel { display: flex; flex-direction: column; gap: 12px; }
.np-state { margin: 0; font-size: 11px; line-height: 1.4286; color: var(--text-tertiary); }
.np-filters { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
.np-search { min-width: 0; flex: 1; box-sizing: border-box; height: 28px; padding: 0 10px; border: 1px solid var(--border-primary); border-radius: 4px; background: var(--surface-input); font-family: inherit; font-size: 11px; color: var(--text-primary); }
.np-cols { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 12px; }
.np-col { display: flex; flex-direction: column; gap: 8px; }
.np-col-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; padding-bottom: 4px; border-bottom: 1px solid var(--border-primary); }
.np-col-label { font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text-tertiary); }
.np-col-count { font-family: var(--desk-mono); font-size: 11px; font-variant-numeric: tabular-nums; color: var(--text-secondary); }
.np-shift { display: flex; flex-direction: column; gap: 8px; }
.np-note { display: flex; flex-direction: column; gap: 4px; padding: 8px 10px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); }
.np-note-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px; }
.np-flight { font-family: var(--desk-mono); font-size: 11px; font-weight: 600; color: var(--text-primary); }
.np-flight.none { font-weight: 400; font-style: italic; color: var(--text-tertiary); }
.np-route, .np-at { font-family: var(--desk-mono); font-size: 10px; color: var(--text-tertiary); }
.np-text { margin: 0; font-size: 11px; line-height: 1.4; color: var(--text-primary); }
.np-text.redacted { font-style: italic; color: var(--text-tertiary); }
.np-meta { font-size: 10px; color: var(--text-secondary); }

/* ── Crew Swap — SWAP board (legacy swap-scenario/board: aircraft, donor strip, wires, rail) ── */
.swap-board, .swap-panel {
  --swap-cyan: var(--accent-primary);
  --swap-amber: var(--accent-warning);
  --swap-violet: var(--accent-violet);
  --swap-red: var(--accent-error);
  --swap-green: var(--accent-success);
}
.swap-board { display: flex; flex-direction: column; gap: 12px; padding: 12px; background: var(--bg-secondary); color: var(--text-primary); border-radius: 12px; }
.swap-stage { position: relative; min-width: 0; overflow: hidden; }
.swap-board-wires { position: absolute; inset: 0; z-index: 5; width: 100%; height: 100%; overflow: hidden; pointer-events: none; }
.swap-wire-stroke.cyan, .swap-wire-flow.cyan { stroke: var(--swap-cyan); }
.swap-wire-stroke.amber, .swap-wire-flow.amber { stroke: var(--swap-amber); }
.swap-wire-stroke.violet, .swap-wire-flow.violet { stroke: var(--swap-violet); }
.swap-wire-stroke.red, .swap-wire-flow.red { stroke: var(--swap-red); }
.swap-wire-dot.cyan { fill: var(--swap-cyan); }
.swap-wire-dot.amber { fill: var(--swap-amber); }
.swap-wire-dot.violet { fill: var(--swap-violet); }
.swap-wire-dot.red { fill: var(--swap-red); }
.swap-wire-flow { animation: swap-flow 1.1s linear infinite; }
.swap-target-wrap { display: flex; justify-content: center; margin-bottom: 16px; }
.swap-target { display: flex; gap: 24px; margin: 0; padding: 16px 20px; border: 1px solid var(--border-secondary); border-radius: 12px; background: var(--surface-card); }
.swap-aircraft { position: relative; width: 190px; height: 252px; flex: none; }
.swap-hull { position: absolute; inset: 0; width: 100%; height: 100%; }
.swap-hull-fill { fill: color-mix(in srgb, var(--bg-tertiary) 80%, var(--border-secondary)); stroke: var(--border-secondary); stroke-width: 1.5; }
.swap-hull-nose { fill: color-mix(in srgb, var(--bg-elevated) 70%, var(--text-tertiary)); }
.swap-slot { position: absolute; z-index: 6; display: flex; flex-direction: column; align-items: center; justify-content: center; width: 52px; height: 30px; border: 1px solid var(--border-secondary); border-radius: 6px; background: var(--surface-hover); font-family: var(--font-mono); font-size: 10px; line-height: 1.1; color: var(--text-tertiary); }
.swap-slot b { font-size: 11px; color: var(--text-secondary); }
.swap-slot.open { border-color: var(--swap-red); background: color-mix(in srgb, var(--swap-red) 12%, transparent); color: var(--swap-red); animation: swap-pulse 1.6s ease-in-out infinite; }
.swap-slot.open b { color: var(--swap-red); }
.swap-target-meta { display: flex; flex-direction: column; justify-content: center; gap: 8px; min-width: 190px; }
.swap-target-flight { font-family: var(--font-sans); font-size: 32px; font-weight: 700; letter-spacing: 0.04em; line-height: 1; }
.swap-target-route, .swap-target-std { display: flex; gap: 8px; font-family: var(--font-mono); font-size: 12px; color: var(--text-secondary); }
.swap-target-std span { color: var(--text-tertiary); }
.swap-target-open { display: flex; flex-wrap: wrap; gap: 6px; }
.swap-target-note { margin: 0; font-family: var(--font-mono); font-size: 10px; color: var(--text-tertiary); }
.swap-legs { display: flex; flex-direction: column; gap: 4px; margin-top: 6px; }
.swap-leg { display: flex; align-items: baseline; gap: 8px; font-size: 11px; line-height: 1.4286; color: var(--text-secondary); }
.swap-leg-flight { font-weight: 600; color: var(--text-primary); }
.swap-leg-route, .swap-leg-time { font-family: var(--font-mono); font-size: 10px; font-variant-numeric: tabular-nums; }
.swap-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; }
@media (min-width: 900px) { .swap-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 340px); } }
.swap-board.max .swap-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 380px); }
.swap-strip { display: flex; flex-direction: row; gap: 16px; overflow-x: auto; padding-bottom: 8px; margin-top: 6px; }
.swap-card { width: 300px; flex: none; border: 1px solid var(--border-primary); border-radius: 10px; background: var(--surface-card); opacity: 0.75; }
.swap-card.wide { width: 100%; max-width: 640px; }
.swap-card.focused { border-color: color-mix(in srgb, var(--swap-cyan) 50%, transparent); box-shadow: var(--shadow-md); opacity: 1; }
.swap-card.selected { box-shadow: inset 0 0 0 1px var(--swap-green); }
.swap-card-focus { display: block; width: 100%; padding: 12px; border: 0; background: transparent; font-family: inherit; text-align: left; color: inherit; cursor: pointer; }
.swap-card-focus:hover { background: var(--surface-hover); }
.swap-card-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px; }
.swap-card-route { font-family: var(--font-sans); font-size: 21px; font-weight: 700; letter-spacing: 0.04em; line-height: 1; }
.swap-card-flight { font-family: var(--font-mono); font-size: 11px; color: var(--text-secondary); }
.swap-tag { margin-left: auto; padding: 2px 6px; border: 1px solid var(--swap-amber); border-radius: 4px; font-family: var(--font-mono); font-size: 10px; color: var(--swap-amber); }
.swap-relative { flex-basis: 100%; text-align: right; font-family: var(--font-mono); font-size: 10px; color: var(--text-secondary); }
.swap-card-meta { display: flex; align-items: center; gap: 8px; margin-top: 4px; font-family: var(--font-mono); font-size: 10px; color: var(--text-tertiary); }
.swap-rank { padding: 0 4px; border-radius: 4px; background: var(--surface-hover); font-weight: 700; font-variant-numeric: tabular-nums; color: var(--text-secondary); }
.swap-kind { font-size: 12px; font-weight: 600; color: var(--text-primary); }
.swap-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.swap-chip { display: inline-flex; align-items: baseline; gap: 4px; padding: 3px 7px; border: 1px solid transparent; border-radius: 6px; font-size: 10px; line-height: 1.2; font-weight: 600; }
.swap-chip b { font-size: 10.5px; font-weight: 500; }
.swap-chip.pull { border-color: color-mix(in srgb, var(--swap-cyan) 45%, transparent); background: color-mix(in srgb, var(--swap-cyan) 12%, transparent); color: var(--swap-cyan); }
.swap-chip.hole { border-color: color-mix(in srgb, var(--swap-amber) 45%, transparent); background: color-mix(in srgb, var(--swap-amber) 12%, transparent); color: var(--swap-amber); }
.swap-chip.hole.open, .swap-chip.open { border-color: color-mix(in srgb, var(--swap-red) 55%, transparent); background: color-mix(in srgb, var(--swap-red) 12%, transparent); color: var(--swap-red); }
.swap-chip.backfill { border-color: color-mix(in srgb, var(--swap-violet) 45%, transparent); background: color-mix(in srgb, var(--swap-violet) 12%, transparent); color: var(--swap-violet); }
.swap-card-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 8px 12px; border-top: 1px solid var(--border-primary); }
.swap-verdict { font-size: 10px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; }
.swap-verdict.legal { color: var(--swap-green); }
.swap-verdict.flagged { color: var(--swap-amber); }
.swap-verdict.illegal { color: var(--swap-red); }
.swap-select { padding: 2px 8px; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--surface-card); font-family: inherit; font-size: 11px; font-weight: 600; color: var(--text-primary); cursor: pointer; }
.swap-select.on { border-color: var(--swap-cyan); color: var(--swap-cyan); }
.swap-timeline { position: relative; height: 44px; margin: 0 12px 10px; border-top: 1px dashed var(--border-primary); }
.swap-timeline-axis { position: absolute; left: 0; right: 0; top: 26px; height: 1px; background: var(--border-secondary); }
.swap-timeline-tick { position: absolute; top: 30px; transform: translateX(-50%); font-family: var(--font-mono); font-size: 9px; color: var(--text-tertiary); }
.swap-timeline-mark { position: absolute; }
.swap-timeline-mark.now { top: 12px; bottom: 0; width: 2px; background: var(--swap-cyan); box-shadow: 0 0 8px var(--swap-cyan); }
.swap-timeline-mark.target { top: 12px; bottom: 0; width: 2px; background: var(--swap-red); }
.swap-timeline-mark.target span { position: absolute; left: -14px; top: -11px; font-family: var(--font-mono); font-size: 9px; color: var(--swap-red); }
.swap-timeline-mark.donor { top: 20px; width: 14%; height: 12px; border: 1px solid color-mix(in srgb, var(--swap-amber) 50%, transparent); border-radius: 3px; background: color-mix(in srgb, var(--swap-amber) 30%, transparent); }
.swap-timeline-mark.donor span { position: absolute; left: 0; top: -18px; transform: translateX(-50%); white-space: nowrap; font-family: var(--font-mono); font-size: 9px; color: var(--text-secondary); }
.swap-legend { display: flex; flex-wrap: wrap; gap: 16px; margin-top: 12px; font-family: var(--font-mono); font-size: 10px; color: var(--text-tertiary); }
.swap-legend-item { display: inline-flex; align-items: center; gap: 6px; }
.swap-legend-item::before { content: ""; width: 16px; height: 3px; border-radius: 2px; background: var(--border-secondary); }
.swap-legend-item.cyan::before { background: var(--swap-cyan); }
.swap-legend-item.amber::before { background: var(--swap-amber); }
.swap-legend-item.violet::before { background: var(--swap-violet); }
.swap-legend-item.red::before { background: var(--swap-red); }
.swap-legend-hint { margin-left: auto; }
.swap-rail { display: flex; flex-direction: column; gap: 14px; min-width: 0; padding: 16px; border: 1px solid var(--border-secondary); border-radius: 12px; background: var(--surface-card); }
.swap-rail-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px; }
.swap-rail-head h4 { margin: 0; font-size: 17px; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; }
.swap-rail-head span { font-family: var(--font-mono); font-size: 11px; color: var(--text-secondary); }
.swap-cost-hint { margin-left: auto; font-size: 9px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-tertiary); }
.swap-steps { display: flex; flex-direction: column; gap: 8px; }
.swap-step { padding: 9px 11px; border: 1px solid var(--border-primary); border-left-width: 3px; border-radius: 8px; background: var(--bg-secondary); }
.swap-step.cyan { border-left-color: var(--swap-cyan); }
.swap-step.amber { border-left-color: var(--swap-amber); }
.swap-step.violet { border-left-color: var(--swap-violet); }
.swap-step.green { border-left-color: var(--swap-green); }
.swap-step.red { border-left-color: var(--swap-red); }
.swap-step-head { display: flex; align-items: baseline; gap: 8px; font-family: var(--font-mono); font-size: 10px; color: var(--text-tertiary); }
.swap-step-head b { font-family: var(--font-sans); font-size: 14px; font-weight: 600; letter-spacing: 0.08em; color: var(--text-primary); }
.swap-step p { margin: 4px 0 0; font-size: 12.5px; line-height: 1.35; color: var(--text-primary); }
.swap-wires { display: flex; flex-direction: column; gap: 4px; }
.swap-wire { padding-left: 10px; border-left: 3px solid var(--border-secondary); font-size: 11px; line-height: 1.4286; color: var(--text-secondary); }
.swap-wire.pull { border-left-color: var(--swap-cyan); }
.swap-wire.hole { border-left-color: var(--swap-amber); }
.swap-wire.hole.open { border-left-color: var(--swap-red); }
.swap-wire.backfill { border-left-color: var(--swap-violet); }
.swap-details-toggle { display: flex; align-items: center; gap: 4px; width: 100%; padding: 0; border: 0; background: transparent; font-family: var(--font-mono); font-size: 11px; color: var(--text-secondary); cursor: pointer; }
.swap-details-toggle:hover { color: var(--text-primary); }
.swap-details-panel { margin-top: 8px; max-height: min(40vh, 24rem); overflow: auto; padding: 12px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--bg-secondary); }
.swap-details-panel.roomy { max-height: none; }
.swap-moves { display: flex; flex-direction: column; gap: 6px; margin: 0; padding-left: 18px; font-size: 12px; color: var(--text-primary); }
.swap-issues { margin: 10px 0 0; padding-left: 18px; font-size: 11px; color: var(--swap-amber); }
.swap-impact { padding: 11px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--bg-secondary); }
.swap-impact h5 { margin: 0 0 8px; font-size: 14px; font-weight: 600; letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-secondary); }
.swap-impact-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
.swap-stat { padding: 6px 8px; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--surface-hover); }
.swap-stat b { display: block; font-size: 21px; font-weight: 700; line-height: 1; }
.swap-stat span { font-size: 10.5px; color: var(--text-tertiary); }
.swap-stat.cyan b { color: var(--swap-cyan); }
.swap-stat.amber b { color: var(--swap-amber); }
.swap-stat.violet b { color: var(--swap-violet); }
.swap-stat.green b { color: var(--swap-green); }
.swap-stat.red b { color: var(--swap-red); }
.swap-stat.text b { color: var(--text-primary); }
.swap-recomputing { margin-left: 8px; font-style: italic; color: var(--text-tertiary); }
.swap-recompute-failed { margin-left: 8px; color: var(--swap-red); }
.swap-board .case-fresh > .case-act { margin-left: auto; padding: 2px 10px; font-size: 11px; }
.swap-rejected { display: flex; flex-direction: column; gap: 6px; margin: 0; padding-left: 18px; }
.swap-board > .case-act { align-self: flex-start; padding: 6px 12px; font-size: 12px; }
.swap-panel.maximized { position: fixed; inset: 0; z-index: 80; overflow: auto; background: var(--bg-secondary); }
.swap-panel-bar { display: flex; justify-content: flex-end; padding: 6px 12px 0; }
.swap-panel-bar > .case-act { padding: 2px 10px; font-size: 11px; }
.swap-tabs { display: flex; flex-wrap: wrap; gap: 6px; }
.swap-tab { padding: 4px 10px; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--surface-card); font-family: var(--font-mono); font-size: 11px; color: var(--text-secondary); cursor: pointer; }
.swap-tab.on { border-color: var(--swap-cyan); color: var(--text-primary); }
.swap-origin { margin: 0; padding: 6px 10px; border-left: 3px solid var(--swap-cyan); border-radius: 4px; background: color-mix(in srgb, var(--swap-cyan) 8%, transparent); font-size: 12px; color: var(--text-primary); }
.swap-trade-trips .case-label { margin-top: 6px; }
.swap-trade { margin: 10px 0 0; padding-left: 18px; font-size: 11px; color: var(--text-secondary); }
.swap-facts { margin: 8px 0 0; padding-left: 16px; font-size: 11px; color: var(--text-secondary); text-align: left; }
.swap-backfill-options { margin-top: 10px; }
.swap-backfill-options ul { display: flex; flex-direction: column; gap: 4px; margin: 6px 0 0; padding: 0; list-style: none; }
.swap-backfill-option { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px; font-size: 11px; }
.swap-backfill-option > .case-act { margin-left: auto; padding: 1px 8px; font-size: 11px; }
@keyframes swap-pulse {
  0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--swap-red) 45%, transparent); }
  50% { box-shadow: 0 0 0 6px color-mix(in srgb, var(--swap-red) 0%, transparent); }
}
@keyframes swap-flow { to { stroke-dashoffset: -26; } }
@media (prefers-reduced-motion: reduce) {
  .swap-slot.open { animation: none; }
  .swap-wire-flow { animation: none; stroke-dasharray: none; }
}
/* Crew console Launchpad board. Scoped so lane, chip, and status names do not leak. */
.lp-board { display: flex; flex-direction: column; gap: 12px; padding: 8px 4px 24px; }
.lp-top, .lp-tools, .lp-card-head, .lp-legend, .lp-queue-toggle { display: flex; align-items: center; gap: 8px; }
.lp-top { justify-content: space-between; flex-wrap: wrap; }
.lp-top h2, .lp-card h3 { margin: 0; }
.lp-sub { color: var(--text-secondary); font-size: 12px; }
.lp-tools button, .lp-zoom button, .lp-qrow button, .lp-kpi {
  height: 28px; padding: 0 10px; border: 1px solid var(--border-primary); border-radius: 8px;
  background: var(--surface-card); color: var(--text-secondary); font: inherit; font-size: 12px; cursor: pointer;
}
.lp-tools button { position: relative; }
.lp-badge { position: absolute; top: -6px; right: -6px; min-width: 16px; padding: 0 4px; border-radius: 999px; background: var(--accent-error); color: #fff; font-size: 10px; font-weight: 700; line-height: 16px; }
.lp-columns { display: flex; gap: 14px; align-items: flex-start; }
.lp-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 12px; }
.lp-card { border: 1px solid var(--border-primary); border-radius: 12px; padding: 12px; background: var(--surface-card); }
.lp-card-head { justify-content: space-between; margin-bottom: 8px; }
.lp-legend { font-size: 11px; color: var(--text-tertiary); }
.lp-legend i, .lp-sev { width: 8px; height: 8px; border-radius: 50%; display: inline-block; }
.lp-legend i.crit, .lp-sev.crit, .lp-chip.crit { background: var(--accent-error); }
.lp-legend i.warn, .lp-sev.warn, .lp-chip.warn { background: var(--accent-warning); }
.lp-legend i.watch, .lp-sev.watch, .lp-chip.watch { background: var(--text-tertiary); }
.lp-wirewrap { display: flex; }
.lp-gutter { position: relative; width: 108px; flex: none; }
.lp-lane { position: absolute; right: 8px; left: 0; text-align: right; font-size: 11px; font-weight: 650; }
.lp-lane small { display: block; font-weight: 600; color: var(--text-tertiary); }
.lp-scroll { flex: 1; min-width: 0; overflow-x: auto; }
.lp-plot { position: relative; }
.lp-band { position: absolute; bottom: 0; }
.lp-band.alt { background: color-mix(in srgb, var(--accent-primary) 8%, transparent); }
.lp-tick { position: absolute; top: 4px; transform: translateX(-50%); font-family: var(--desk-mono, var(--font-mono)); font-size: 10px; color: var(--text-tertiary); }
.lp-past { position: absolute; left: 0; bottom: 0; background: color-mix(in srgb, var(--bg-primary) 55%, transparent); pointer-events: none; }
.lp-now { position: absolute; top: 0; bottom: 0; width: 2px; background: var(--accent-primary); z-index: 2; }
.lp-nowtag { position: absolute; transform: translateX(-50%); font-size: 10px; font-weight: 600; color: var(--text-on-accent, #0a0f1a); background: var(--accent-primary); border-radius: 999px; padding: 1px 6px; white-space: nowrap; }
.lp-line { position: absolute; left: 0; right: 0; height: 1px; background: var(--border-primary); }
.lp-chip { position: absolute; z-index: 3; height: 22px; padding: 0 8px; border-radius: 999px; border: 0; font-size: 11px; font-weight: 700; color: #0a0f1a; white-space: nowrap; cursor: pointer; }
.lp-chip.overdue { outline: 1px dashed var(--text-primary); outline-offset: 1px; }
.lp-chip.reviewed { opacity: 0.55; }
.lp-queue-toggle { width: 100%; background: none; border: 0; padding: 0; text-align: left; cursor: pointer; color: inherit; }
.lp-count { font-size: 11px; font-weight: 700; background: var(--accent-error); color: #0a0f1a; border-radius: 999px; padding: 1px 7px; }
.lp-qrow, .lp-delay-row { width: 100%; display: grid; grid-template-columns: 10px 1fr auto auto auto; gap: 10px; align-items: center; padding: 8px 0; border: 0; border-top: 1px solid var(--border-primary); background: transparent; text-align: left; color: inherit; }
.lp-delay-row { grid-template-columns: 1fr auto; cursor: pointer; }
.lp-when { font-family: var(--desk-mono, var(--font-mono)); font-size: 12px; color: var(--text-secondary); }
.lp-status { width: 220px; flex: none; position: sticky; top: 8px; display: flex; flex-direction: column; gap: 8px; }
.lp-status h3 { margin: 0; font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-tertiary); }
.lp-kpi { display: block; width: 100%; height: auto; min-height: 64px; text-align: left; padding: 8px 10px; }
.lp-kpi.off { opacity: 0.7; cursor: default; }
.lp-kpi-title { font-size: 11px; font-weight: 650; }
.lp-kpi-value { margin-top: 4px; font-size: 18px; font-weight: 700; color: var(--text-primary); }
.lp-kpi-value.na, .lp-kpi-foot { font-size: 11px; font-weight: 600; color: var(--text-tertiary); }
.lp-hover { position: fixed; z-index: 60; max-width: 320px; pointer-events: none; padding: 8px 10px; border-radius: 10px; border: 1px solid var(--border-secondary); background: var(--bg-elevated); box-shadow: var(--shadow-md); }
.lp-hover-k { font-size: 10px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-tertiary); margin-bottom: 6px; }
.lp-hover-row { display: flex; gap: 8px; align-items: baseline; border-left: 3px solid var(--text-tertiary); padding-left: 8px; }
.lp-hover-row.crit { border-left-color: var(--accent-error); }
.lp-hover-row.warn { border-left-color: var(--accent-warning); }
.lp-hover-time { font-family: var(--desk-mono, var(--font-mono)); font-size: 10px; font-weight: 700; }
.lp-scrim { position: fixed; inset: 0; z-index: 40; background: var(--bg-overlay, rgba(0, 0, 0, 0.6)); display: flex; justify-content: center; padding: 12vh 16px 16px; }
.lp-palette { width: min(520px, 100%); background: var(--bg-elevated); border: 1px solid var(--border-secondary); border-radius: 16px; padding: 10px; }
.lp-palette input { width: 100%; box-sizing: border-box; margin-bottom: 8px; background: var(--surface-input); border: 1px solid var(--border-primary); border-radius: 10px; padding: 8px 10px; color: inherit; font: inherit; }
.lp-jump { width: 100%; text-align: left; background: transparent; border: 0; border-radius: 8px; padding: 8px 10px; display: flex; justify-content: space-between; gap: 8px; color: inherit; cursor: pointer; }
.lp-jump:hover:not(:disabled) { background: var(--surface-hover); }
.lp-jump:disabled { color: var(--text-disabled); cursor: not-allowed; }
.lp-empty { color: var(--text-tertiary); margin: 8px 0; }
@media (max-width: 1100px) {
  .lp-columns { display: block; }
  .lp-status { width: auto; position: static; margin-top: 14px; }
}

.np-sub { margin: 0; font-family: var(--desk-mono); font-size: 11px; color: var(--text-tertiary); }
.np-hint { margin: 0; font-size: 12px; line-height: 1.45; color: var(--text-tertiary); }
.np-summary { display: flex; align-items: center; justify-content: space-between; gap: 12px; width: 100%; text-align: left; padding: 10px 12px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--bg-tertiary); color: var(--text-primary); font-family: inherit; font-size: 13px; cursor: pointer; }
.np-summary strong { font-weight: 600; margin-right: 8px; }
.np-summary span { color: var(--text-tertiary); }
.np-viewall { border: 1px dashed var(--border-secondary); background: transparent; color: var(--text-secondary); border-radius: 8px; padding: 6px 10px; font-family: inherit; font-size: 12px; cursor: pointer; }
.np-banks { display: grid; grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); gap: 8px; }
.np-bank { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; text-align: left; padding: 10px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); color: var(--text-primary); font-family: inherit; cursor: pointer; }
.np-bank:hover { background: var(--surface-hover); }
.np-col-count.none { color: var(--text-disabled); }
.np-back { border: 0; background: transparent; color: var(--text-secondary); font-family: inherit; font-size: 13px; padding: 0; cursor: pointer; }
.np-add { border: 0; border-radius: 8px; background: var(--accent-primary); color: var(--text-inverse); font-family: inherit; font-weight: 700; font-size: 13px; padding: 6px 12px; cursor: pointer; }
.np-add:disabled { opacity: 0.5; cursor: default; }
.np-cancel { border: 1px solid var(--border-primary); border-radius: 8px; background: transparent; color: var(--text-secondary); font-family: inherit; font-size: 13px; padding: 6px 12px; cursor: pointer; }
.np-bank-select, .np-date { flex: 0 0 auto; }
.np-compose { display: flex; flex-direction: column; gap: 12px; }
.np-compose-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.np-field { display: flex; flex-direction: column; gap: 6px; font-size: 11px; letter-spacing: 0.04em; color: var(--text-tertiary); }
.np-field input, .np-field select, .np-field textarea { letter-spacing: 0; font-size: 13px; color: var(--text-primary); background: var(--surface-input); border: 1px solid var(--border-primary); border-radius: 8px; padding: 8px 10px; font-family: inherit; }
.np-field textarea { min-height: 96px; resize: vertical; }
.np-fine { margin: 0; padding: 10px 12px; border-radius: 8px; background: var(--bg-tertiary); color: var(--text-tertiary); font-size: 12px; line-height: 1.4; }
.np-compose-actions { display: flex; justify-content: flex-end; gap: 8px; }

/* A read still in flight says so with a spinner beside its words, wherever it sits. */
.ui-loading { display: flex; align-items: center; gap: 8px; }
.ui-loading::before { content: ""; flex: none; width: 12px; height: 12px; box-sizing: border-box; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: ui-loading-spin .8s linear infinite; }
@keyframes ui-loading-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .ui-loading::before { animation-duration: 2.4s; } }

/* @dcortex/canvas-ui — D12 component styles (rearch/06; the legacy dCortex Console is the
 * pixel source of truth — apps/canvas/design/legacy-console-reference.html). ONE styling
 * system for the whole console: the chrome (header/rail/review/toolbar), the KPI grid, the
 * detail panel, the timeline. Consumes tokens.css — zero hardcoded colors except the brand
 * logo gradient, which 06 pins. Every screen that composes these components inherits the
 * legacy look; there is no second/per-screen stylesheet. */

/* ---- Shell (06 §layout) ---- */
.shell-root { display: flex; flex-direction: column; height: 100vh; overflow: hidden; }
.shell-header {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 0 18px; height: 62px; border-bottom: 1px solid var(--border-primary); background: var(--bg-elevated); flex: none;
}
.shell-brand { display: flex; align-items: center; gap: 11px; }
.shell-logo {
  width: 34px; height: 34px; border-radius: 9px; flex: none;
  background: linear-gradient(135deg, #101828, #1e3a8a); /* the brand tile, the console navy in both themes */
  display: grid; place-items: center; color: #3b82f6; box-shadow: var(--shadow-sm);
}
.shell-logo svg { width: 20px; height: 20px; }
/* tenant/airline logo tile (header brands to the operating customer) */
.shell-logo-img { width: 34px; height: 34px; border-radius: 9px; flex: none; object-fit: cover; box-shadow: var(--shadow-sm); }
.shell-brand b { font-size: 15px; font-weight: 700; letter-spacing: -0.01em; line-height: 1.1; }
.shell-brand small { display: block; font-size: 11px; color: var(--text-tertiary); }
.shell-controls { display: flex; align-items: center; gap: 8px; }
.shell-body { display: flex; flex: 1; min-height: 0; }
.shell-rail {
  width: 55px; flex: none; display: flex; flex-direction: column; align-items: center;
  gap: 6px; padding: 12px 0; border-right: 1px solid var(--border-primary); background: var(--bg-secondary);
}
.rail-item {
  width: 40px; height: 40px; display: grid; place-items: center;
  border: none; border-radius: var(--radius-lg); background: transparent;
  color: var(--text-tertiary); cursor: pointer; text-decoration: none;
}
.rail-item:hover { background: var(--surface-hover); color: var(--text-primary); }
.rail-item.active { background: var(--accent-primary); color: var(--text-on-accent); }
.rail-item svg { width: 20px; height: 20px; }
.shell-sidebar {
  width: 280px; flex: none; border-right: 1px solid var(--border-primary); background: var(--bg-primary);
  display: flex; flex-direction: column; overflow: hidden; transition: width 0.2s ease, opacity 0.15s;
}
.shell-sidebar.collapsed { width: 0; opacity: 0; border-right: 0; pointer-events: none; }
/* main is the scroll container (back-compat: every screen's content scrolls here); a
 * console-toolbar sticks to the top while the content below it scrolls. */
.shell-main { flex: 1; min-width: 0; overflow: auto; display: flex; flex-direction: column; }
.shell-content { padding: 18px; }

/* ---- Console header chrome (ConsoleHeader) ---- */
/* Legacy header controls: uniform 32px, radius-lg, 1px border; alert red-tinted with a triangle-alert
   icon + count badge; EN/ES a segmented pill (blue active); theme a bordered sun/moon button. */
.bell {
  position: relative; width: 32px; height: 32px; box-sizing: border-box; border-radius: var(--radius-lg); display: grid; place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent-error), transparent 65%);
  background: color-mix(in srgb, var(--accent-error), transparent 90%); color: var(--accent-error); cursor: pointer;
}
.bell:hover { background: color-mix(in srgb, var(--accent-error), transparent 84%); }
.bell .ct {
  position: absolute; top: -6px; right: -6px; min-width: 18px; height: 18px; border-radius: 999px; background: var(--accent-error);
  color: #fff; font-size: 10px; font-weight: 700; display: grid; place-items: center; padding: 0 4px;
}
.lang { display: inline-flex; gap: 2px; padding: 2px; height: 32px; box-sizing: border-box; align-items: center; border: 1px solid var(--border-primary); border-radius: var(--radius-lg); background: var(--bg-secondary); }
.lang button { font: inherit; font-size: 11px; font-weight: 600; height: 24px; display: inline-flex; align-items: center; padding: 0 12px; border: 0; border-radius: var(--radius-md); cursor: pointer; background: transparent; color: var(--text-secondary); }
.lang button:hover { color: var(--text-primary); }
.lang button.on { background: var(--accent-primary); color: var(--text-on-accent); }
.zone-select { font: inherit; font-size: 11px; font-weight: 600; height: 32px; max-width: 190px; box-sizing: border-box; padding: 0 8px; border: 1px solid var(--border-primary); border-radius: var(--radius-lg); background: var(--bg-secondary); color: var(--text-secondary); cursor: pointer; }
.zone-select:hover { color: var(--text-primary); }
.user {
  display: inline-flex; align-items: center; gap: 8px; height: 32px; border: 1px solid var(--border-primary); border-radius: var(--radius-lg);
  padding: 0 12px; font-size: 12px; color: var(--text-secondary); cursor: pointer; background: var(--bg-secondary);
}
.user .user-avatar { flex: none; color: var(--text-tertiary); }
.user .user-name { max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.user .user-caret { flex: none; color: var(--text-tertiary); }

/* ---- User dropdown menu (header user → Logout) ---- */
.usermenu { position: relative; display: inline-flex; }
.usermenu .user { font-family: inherit; }
.usermenu .user:hover { background: var(--surface-hover); color: var(--text-primary); }
.usermenu-scrim { position: fixed; inset: 0; z-index: 40; border: 0; padding: 0; margin: 0; background: transparent; cursor: default; }
.usermenu-pop {
  position: absolute; right: 0; top: calc(100% + 6px); z-index: 41; min-width: 168px; padding: 4px;
  display: flex; flex-direction: column; background: var(--surface-card); border: 1px solid var(--border-primary);
  border-radius: var(--radius-lg); box-shadow: var(--shadow-md);
}
.usermenu-item {
  font: inherit; font-size: 12.5px; text-align: left; padding: 8px 12px; border: 0; border-radius: var(--radius-md);
  background: transparent; color: var(--text-secondary); cursor: pointer;
}
.usermenu-item:hover { background: var(--surface-hover); color: var(--text-primary); }

/* ---- Icon button (06 §buttons) ---- */
.iconbtn {
  width: 32px; height: 32px; display: inline-grid; place-items: center;
  background: var(--bg-secondary); border: 1px solid var(--border-primary);
  border-radius: var(--radius-lg); color: var(--text-secondary); cursor: pointer; font-size: 15px;
}
.iconbtn:hover { background: var(--surface-hover); color: var(--text-primary); }

/* ---- Review sidebar (ReviewSidebar) — same height + tab styling as the toolbar so the two panel
   headers align exactly (legacy: both tab rows share a baseline). ---- */
.review-head { display: flex; align-items: center; gap: 6px; padding: 0 12px; height: 48px; border-bottom: 1px solid var(--border-primary); flex: none; }
.review-tab {
  font-size: 11px; font-weight: 500; border-radius: var(--radius-md); padding: 4px 8px; border: 0;
  background: transparent; color: var(--text-secondary); cursor: pointer; display: inline-flex; align-items: center; gap: 5px;
}
/* Active-toggle tabs: the SELECTED tab gets a tinted rounded chip — Review → amber, Done → green — and
   the other resets to gray. Inactive tabs hover to a surface tint. */
.review-tab:not(.on):hover { background: var(--surface-hover); color: var(--text-primary); }
.review-tab.on:first-child {
  background: color-mix(in srgb, var(--accent-warning), transparent 85%); color: var(--cell-amber-tx);
}
.review-tab.on:nth-child(2) {
  background: color-mix(in srgb, var(--accent-success), transparent 85%); color: var(--accent-success);
}
.review-cnt {
  min-width: 16px; height: 15px; border-radius: 999px; display: inline-grid; place-items: center; font-size: 10px; font-weight: 600; padding: 0 4px;
  background: var(--surface-hover); color: var(--text-tertiary);
}
.review-tab.on:first-child .review-cnt { background: color-mix(in srgb, var(--accent-warning), transparent 75%); color: var(--cell-amber-tx); }
.review-tab.on:nth-child(2) .review-cnt { background: color-mix(in srgb, var(--accent-success), transparent 75%); color: var(--accent-success); }
/* review-header icon controls (refresh + close) — legacy: ~26px, 6px pad, radius-md; first one right-aligned. */
.review-tab + .review-icon { margin-left: auto; }
.review-icon { width: 26px; height: 26px; display: inline-grid; place-items: center; border-radius: var(--radius-md); border: 0; background: transparent; cursor: pointer; }
.review-refresh { color: var(--text-primary); }
.review-close { color: var(--text-tertiary); }
.review-icon:hover { background: var(--surface-hover); color: var(--text-primary); }
.review-body { overflow: auto; padding: 12px 14px; display: flex; flex-direction: column; gap: 16px; }
.review-badge {
  display: inline-flex; align-items: center; gap: 5px; border-radius: var(--radius-md); padding: 3px 9px; font-size: 11px; font-weight: 600;
  background: color-mix(in srgb, var(--accent-warning), transparent 84%); color: var(--accent-warning);
}

/* ---- Console toolbar (Toolbar / view tabs + date chips) ---- */
.console-toolbar { position: sticky; top: 0; z-index: 3; display: flex; align-items: center; gap: 14px; padding: 0 18px; min-height: 48px; border-bottom: 1px solid var(--border-primary); background: var(--bg-primary); flex-wrap: wrap; }
.toolbar-dates { display: flex; gap: 6px; align-items: center; flex-wrap: wrap; }
/* Match legacy console toolbar: 11px chips, tighter padding; inactive date chips carry a surface tint. */
.console-toolbar .chip { font-size: 11px; padding: 4px 10px; gap: 5px; }
.toolbar-dates .chip:not(.active) { background: var(--bg-secondary); }
.chip-icon { display: inline-flex; align-items: center; }
.chip-icon svg { width: 13px; height: 13px; display: block; }
.toolbar-spacer { flex: 1; }

/* ---- Segmented chips (06 §toolbar) ---- */
/* Legacy view-switcher = a JOINED segmented group (tabs touch; only the group ends are rounded). */
.segmented { display: inline-flex; gap: 0; padding: 3px; background: var(--bg-secondary); border: 1px solid var(--border-primary); border-radius: var(--radius-lg); }
.segmented .chip { border-radius: 0; }
.segmented .chip:first-child { border-radius: var(--radius-md) 0 0 var(--radius-md); }
.segmented .chip:last-child { border-radius: 0 var(--radius-md) var(--radius-md) 0; }
.chip-count {
  margin-left: 6px; min-width: 18px; height: 18px; border-radius: 999px; display: inline-grid; place-items: center; padding: 0 5px; font-size: 10px; font-weight: 700;
  background: color-mix(in srgb, var(--text-tertiary), transparent 80%);
}

/* ---- KPI grid + card (06 §components) ---- */
.kpi-grid { display: grid; gap: 12px; grid-template-columns: repeat(8, minmax(0, 1fr)); }
@media (max-width: 1500px) { .kpi-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
@media (max-width: 820px) { .kpi-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
/* Dashboard two-panel split (legacy SupervisorDashboard): a FIXED top KPI strip + a detail panel below
   that scrolls independently. .dash-split fills the shell-main column; only .dash-detail scrolls. */
.dash-split { flex: 1; min-height: 0; display: flex; flex-direction: column; padding: 18px; gap: 12px; }
.dash-strip { flex: none; }
.dash-detail { flex: 1; min-height: 0; overflow-y: auto; border-top: 1px solid var(--border-primary); }
.dash-detail-empty { display: flex; align-items: center; justify-content: center; height: 100%; min-height: 160px; color: var(--text-tertiary); font-size: 13px; text-align: center; padding: 24px; }
/* Inline task list for the task-derived KPI details (uncrewed / absences). */
.dash-task-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.dash-task-item { width: 100%; text-align: left; background: var(--surface-card); border: 1px solid var(--border-primary); border-radius: var(--radius-md); padding: 10px 12px; font-size: 13px; color: var(--text-primary); cursor: pointer; transition: 0.12s; }
.dash-task-item:hover { background: var(--surface-hover); border-color: var(--border-secondary); }
/* Legacy console KPI band: one horizontal row that scrolls sideways on narrow widths instead of wrapping.
   The doubled selector outranks the .kpi-grid @media rules above, so it stays single-row at every width. */
.kpi-strip { overflow-x: auto; padding-bottom: 2px; }
.kpi-grid.kpi-grid--strip { grid-template-columns: none; grid-auto-flow: column; grid-auto-columns: minmax(150px, 1fr); gap: 8px; }
.kpi-card {
  display: flex; flex-direction: column; min-height: 152px;
  background: var(--surface-card); border: 1px solid var(--border-primary);
  border-radius: var(--radius-xl); padding: 13px 13px 12px; cursor: pointer; box-shadow: var(--shadow-sm); transition: 0.15s;
}
.kpi-card:hover { border-color: var(--border-secondary); box-shadow: var(--shadow-md); }
.kpi-card.selected {
  border-color: var(--accent-primary); box-shadow: 0 0 0 1px var(--accent-primary);
  background: color-mix(in srgb, var(--accent-primary), transparent 93%);
}
.kpi-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 6px; }
.kpi-title { flex: 1; min-width: 0; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text-tertiary); line-height: 1.35; }
/* Legacy card chrome: top-right refresh control (rendered only when the card supplies onRefresh). */
.kpi-refresh {
  flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px;
  padding: 0; border: 1px solid var(--border-primary); border-radius: var(--radius-md); background: transparent;
  color: var(--text-tertiary); cursor: pointer; transition: 0.15s;
}
.kpi-refresh:hover { background: var(--surface-hover); color: var(--text-primary); }
.kpi-refresh:disabled { cursor: not-allowed; opacity: 0.5; }
.kpi-refresh.spinning svg { animation: kpi-spin 0.8s linear infinite; }
@keyframes kpi-spin { to { transform: rotate(360deg); } }
/* Dashboard strip only: compact card height + hover tint to match legacy's KpiStrip proportions. */
.kpi-grid--strip .kpi-card { min-height: 108px; padding: 8px; }
.kpi-strip .kpi-card:hover { background: var(--surface-hover); }
.kpi-value { font-size: 32px; font-weight: 700; letter-spacing: -0.02em; margin: 6px 0 auto; font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.kpi-value.red { color: var(--accent-error); }
.kpi-value.green { color: var(--accent-success); }
.kpi-value.amber { color: var(--accent-warning); }
.kpi-value.teal { color: var(--accent-teal); }
.kpi-pills { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 8px; }
/* Legacy KpiSplitFooter: two stacked columns pushed to the card edges (left tags | right tags). */
.kpi-pills.split { flex-wrap: nowrap; justify-content: space-between; align-items: flex-end; gap: 6px; }
.kpi-pills-group { display: flex; flex-direction: column; gap: 4px; align-items: flex-start; min-width: 0; }
/* right column keeps its natural single-line width (legacy `shrink-0`) with single-line chips; the left
   column's chips hug their wrapped text (cap forces "Flight Attendants" to 2 lines, shorter chips stay 1). */
.kpi-pills-group.right { align-items: flex-end; text-align: right; flex-shrink: 0; }
.kpi-pills-group.right .pill { white-space: nowrap; }
.kpi-grid--strip .kpi-pills-group:not(.right) .pill { max-width: 52px; }
/* Dashboard strip cards match legacy KpiStrip typography: 20px value, brighter (primary) title, 9px
   rounded-SQUARE chips (not pills), and a consistent title→value gap via a min-height title row. */
.kpi-grid--strip .kpi-head { min-height: 30px; }
.kpi-grid--strip .kpi-value { font-size: 20px; line-height: 1; margin: 7px 0 auto; }
.kpi-grid--strip .kpi-title { color: var(--text-primary); }
.kpi-grid--strip .pill { font-size: 9px; padding: 2px 6px; line-height: 1.25; border-radius: 4px; }

/* ---- Detail panel (DetailPanel) ---- */
.panel { margin-top: 18px; background: var(--surface-card); border: 1px solid var(--border-primary); border-radius: var(--radius-xl); padding: 16px 18px; box-shadow: var(--shadow-sm); }
.panel .panel-head { display: flex; align-items: center; gap: 8px; font-size: 14px; font-weight: 600; color: var(--text-primary); }
.panel .panel-empty { margin-top: 8px; font-size: 13px; color: var(--text-tertiary); }

/* ---- Timeline Gantt (06 §components) ---- */
.gantt { overflow-x: auto; }
.gantt-axis { position: relative; height: 28px; margin-left: var(--labelW); border-bottom: 1px solid var(--border-primary); background: var(--bg-primary); }
.gantt-tz { position: sticky; left: 0; font-size: 10px; color: var(--text-tertiary); padding-right: 8px; }
.gantt-tick { position: absolute; top: 6px; transform: translateX(-50%); font-size: 10px; color: var(--text-tertiary); }
.gantt-row { display: flex; align-items: center; height: var(--rowH); }
.gantt-label { width: var(--labelW); flex: none; position: sticky; left: 0; font-size: 11px; color: var(--text-secondary); background: var(--bg-primary); }
.gantt-track { position: relative; height: 100%; background-image: repeating-linear-gradient(to right, var(--grid-line) 0 1px, transparent 1px var(--hourW)); }
.gantt-bar { position: absolute; top: 4px; bottom: 4px; border-radius: 5px; display: inline-flex; align-items: center; padding: 0 6px; font-size: 10px; white-space: nowrap; overflow: hidden; }
.gantt-bar:hover { filter: brightness(1.15); }
.gantt-bar.sky { background: var(--sky-bg); border: 1px solid var(--sky-bd); color: var(--sky-tx); }
.gantt-bar.green { background: var(--emer-bg); border: 1px solid var(--emer-bd); color: var(--emer-tx); }
.gantt-bar.red { background: var(--red-bg); border: 1px solid var(--red-bd); color: var(--red-tx); }
.gantt-tag { position: absolute; top: 50%; transform: translateY(-50%); border-radius: 999px; padding: 1px 8px; font-size: 10px; font-weight: 600; white-space: nowrap; }
.gantt-tag.early { background: var(--tag-early-bg); color: var(--tag-early-tx); }
.gantt-tag.delay { background: var(--tag-delay-bg); color: var(--tag-delay-tx); }
.gantt-task-dot { position: absolute; top: 2px; width: 5px; height: 5px; border-radius: 50%; background: var(--accent-error); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent-error), transparent 75%); }

/* shared spinner (RefreshButton) */
@keyframes dc-spin { to { transform: rotate(360deg); } }

/* ───────────────────────── Controller desk (D2) ─────────────────────────
 * Matched to legacy /desk (copa-preprod 61df4191; knowledge-base/features/controller-desk.md §D2 visual spec).
 * Ruling E: the desk renders in the system font stack, scoped here — the rest of Canvas keeps its fonts.
 * Colours are tokens only; legacy's own hard-coded Tailwind colours (cyan selection) are noted where used. */
.desk-root {
  --desk-font: var(--font-sans);
  --desk-mono: var(--font-mono);
  display: flex; flex-direction: column; height: 100vh; overflow: hidden;
  background: var(--bg-primary); color: var(--text-primary);
  font-family: var(--desk-font); font-size: 16px; line-height: 1.5;
  -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale;
}
.desk-root button { font-family: inherit; }

/* header — navbar.tsx on /desk: sticky, 95% elevated fill, compact 3-column grid */
.desk-header {
  position: sticky; top: 0; z-index: 50; flex-shrink: 0;
  border-bottom: 1px solid var(--border-primary);
  background: color-mix(in srgb, var(--bg-elevated) 95%, transparent);
  backdrop-filter: blur(4px); box-shadow: var(--shadow-sm);
}
.desk-header-grid { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 8px; padding: 4px 16px; }
@media (min-width: 768px) { .desk-header-grid { padding: 4px 24px; } }
.desk-brand { display: flex; align-items: center; gap: 8px; min-width: 0; }
.desk-logo { display: flex; align-items: center; justify-content: center; overflow: hidden; width: 24px; height: 24px; border-radius: 8px; background: color-mix(in srgb, var(--accent-primary) 10%, transparent); color: var(--accent-primary); }
.desk-logo svg { width: 16px; height: 16px; }
.desk-logo img { width: 100%; height: 100%; object-fit: contain; }
.desk-org { font-size: 12px; line-height: 16px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary); white-space: nowrap; }
.desk-center { min-width: 0; justify-self: center; display: flex; align-items: center; justify-content: center; gap: 12px; }
.desk-right { display: flex; align-items: center; justify-content: flex-end; gap: 8px; justify-self: end; font-size: 12px; }

/* navControlStyles.ts — segment group, segments, control buttons */
.nav-seg-group { display: inline-flex; align-items: center; height: 28px; box-sizing: border-box; padding: 1px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); }
.nav-seg-slot { display: inline-flex; align-items: center; }
.nav-seg-divider { display: inline-block; width: 1px; height: 16px; margin: 0 2px; background: var(--border-primary); }
.nav-seg { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 10px; border: 0; border-radius: 6px; background: transparent; color: var(--text-secondary); font-size: 11px; line-height: 16.5px; font-weight: 600; white-space: nowrap; cursor: pointer; transition: background-color 0.15s, color 0.15s; }
.nav-seg:hover { background: var(--surface-hover); color: var(--text-primary); }
.nav-seg.on, .nav-seg.on:hover { background: var(--accent-primary); color: var(--text-on-accent); box-shadow: var(--shadow-sm); }
.nav-seg svg { flex-shrink: 0; }
.nav-seg-group.uppercase .nav-seg { text-transform: uppercase; letter-spacing: 0.025em; }
.nav-ctl { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 28px; box-sizing: border-box; padding: 0 10px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); color: var(--text-primary); font-size: 11px; font-weight: 600; white-space: nowrap; cursor: pointer; transition: background-color 0.15s, color 0.15s; }
.nav-ctl:hover, .nav-ctl.open { background: var(--surface-hover); }
.nav-ctl:focus-visible, .nav-seg:focus-visible { outline: 2px solid var(--accent-primary); outline-offset: 1px; }
.nav-ctl-icon { width: 28px; padding: 0; color: var(--text-secondary); }
.nav-ctl-icon:hover { color: var(--text-primary); }
.desk-profile { max-width: 180px; color: var(--text-primary); font-size: 12px; font-weight: 500; }
.desk-profile-name { overflow: hidden; text-overflow: ellipsis; }
.desk-profile:hover { border-color: var(--border-secondary); }
.desk-profile .desk-chevron { transition: transform 0.15s; flex-shrink: 0; }
.desk-profile.open .desk-chevron { transform: rotate(180deg); }

/* popovers — Jump menu (DeskJumpMenu.tsx) and the profile menu */
.desk-popover-anchor { position: relative; display: inline-flex; }
.desk-menu { position: absolute; top: calc(100% + 4px); left: 0; z-index: 70; min-width: 192px; padding: 4px 0; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--bg-elevated); box-shadow: var(--shadow-lg); }
.desk-menu-right { left: auto; right: 0; top: calc(100% + 8px); border-radius: 8px; padding: 4px; }
.desk-menu-item { display: flex; align-items: center; gap: 8px; width: 100%; padding: 6px 12px; border: 0; background: transparent; color: var(--text-primary); font-size: 14px; line-height: 20px; text-align: left; cursor: pointer; }
.desk-menu-item svg { width: 14px; height: 14px; color: var(--text-secondary); }
.desk-menu-item:hover { background: var(--surface-hover); }
.desk-menu-right .desk-menu-item { border-radius: 6px; font-size: 12px; }
.desk-menu-item.danger:hover { color: var(--accent-error); background: color-mix(in srgb, var(--accent-error) 10%, transparent); }

/* date picker popover (PanamaSingleDatePicker chrome + .crew-picker) */
.desk-cal { position: absolute; top: calc(100% + 8px); left: 0; z-index: 70; padding-bottom: 10px; border: 1px solid var(--border-primary); border-radius: 12px; background: var(--bg-elevated); box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25); }
.desk-cal-hint { margin: 0; padding: 10px 12px 0; font-size: 11px; line-height: 16px; color: var(--text-tertiary); }
.desk-cal-caption { display: flex; align-items: center; justify-content: space-between; padding: 8px 12px 4px; font-size: 14px; font-weight: 600; color: var(--text-primary); }
.desk-cal-nav { display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; border: 0; border-radius: 6px; background: transparent; color: var(--text-secondary); cursor: pointer; }
.desk-cal-nav:hover { background: var(--surface-hover); color: var(--text-primary); }
.desk-cal-grid { border-collapse: collapse; margin: 0 12px; }
.desk-cal-grid th { width: 36px; height: 28px; font-size: 12px; font-weight: 500; color: var(--text-tertiary); }
.desk-cal-grid td { width: 36px; height: 36px; padding: 0; text-align: center; }
.desk-cal-day { width: 34px; height: 34px; border: 0; border-radius: 6px; background: transparent; color: var(--text-primary); font-size: 13px; cursor: pointer; }
.desk-cal-day:hover { background: var(--surface-hover); }
.desk-cal-day.today { color: var(--accent-primary); font-weight: 600; }
.desk-cal-day.selected, .desk-cal-day.selected:hover { background: var(--accent-primary); color: var(--text-on-accent); }
.desk-cal-footer { display: flex; justify-content: flex-end; gap: 8px; padding: 8px 12px 0; }
.desk-cal-cancel, .desk-cal-apply { padding: 4px 12px; border-radius: 6px; font-size: 11px; line-height: 16px; cursor: pointer; }
.desk-cal-cancel { border: 1px solid var(--border-primary); background: var(--surface-card); color: var(--text-primary); font-weight: 500; }
.desk-cal-apply { border: 0; background: var(--accent-primary); color: var(--text-on-accent); font-weight: 600; }

/* top pane + KPI strip (DeskTopPane.tsx, DeskOpsKpiStrip.tsx, DeskKpiCard.tsx) */
.desk-top-pane { position: relative; z-index: 30; display: flex; flex-shrink: 0; align-items: stretch; gap: 8px; padding: 7px 10px; border-bottom: 1px solid var(--border-primary); background: var(--bg-secondary); }
.desk-top-scroll { display: flex; flex: 1; min-width: 0; align-items: stretch; gap: 6px; overflow-x: auto; }
.desk-ops { display: flex; align-items: center; padding: 0 4px; font-size: 9px; line-height: 13.5px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--text-primary); }
.desk-kpi-list { display: flex; flex-wrap: nowrap; align-items: stretch; gap: 5px; min-width: 0; }
.desk-kpi { position: relative; display: flex; flex-shrink: 0; min-width: 68px; max-width: 108px; }
.desk-kpi-btn { display: flex; flex-direction: column; justify-content: space-between; width: 100%; height: 100%; box-sizing: border-box; overflow: hidden; padding: 6px 9px; border: 1px solid var(--border-primary); border-radius: 9px; background: var(--surface-card); color: var(--text-primary); text-align: left; cursor: pointer; transition: background-color 0.15s; }
.desk-kpi-btn.has-refresh { padding-right: 24px; }
.desk-kpi-btn:hover { background: var(--surface-hover); }
.desk-kpi-btn.selected, .desk-kpi-btn.selected:hover { background: color-mix(in srgb, var(--accent-primary) 15%, transparent); border-color: var(--accent-primary); }
.desk-kpi-count { font-family: var(--desk-mono); font-size: 16px; line-height: 1; font-weight: 600; color: var(--text-primary); }
.desk-kpi-count.invisible { visibility: hidden; }
.desk-kpi-label { font-size: 9.5px; line-height: 1.25; font-weight: 500; letter-spacing: 0.04em; text-transform: uppercase; text-wrap: pretty; color: var(--text-primary); }
.desk-kpi-refresh { position: absolute; top: 4px; right: 4px; display: inline-flex; align-items: center; justify-content: center; width: 16px; height: 16px; padding: 0; border: 0; border-radius: 4px; background: transparent; color: var(--text-tertiary); cursor: pointer; }
.desk-kpi-refresh:hover { background: var(--surface-hover); color: var(--text-primary); }
.desk-kpi-refresh:disabled { cursor: not-allowed; opacity: 0.6; }
.desk-kpi-refresh.spinning svg { animation: dc-spin 1s linear infinite; }
@media (prefers-reduced-motion: reduce) { .desk-kpi-refresh.spinning svg { animation: none; } }

/* main area (DeskShell.tsx / DeskRightPane.tsx) */
.desk-main { position: relative; display: flex; flex: 1; min-height: 0; flex-direction: column; overflow: auto; background: var(--bg-primary); }
.desk-close { position: absolute; top: 8px; right: 12px; z-index: 10; display: inline-flex; align-items: center; justify-content: center; width: 24px; height: 24px; padding: 0; border: 0; border-radius: 6px; background: transparent; color: var(--text-secondary); cursor: pointer; }
.desk-close:hover { background: var(--surface-hover); color: var(--text-primary); }
.desk-state { margin: auto; padding: 24px; font-size: 13px; color: var(--text-tertiary); text-align: center; }

/* ── Controller desk D3 — the Monitor matrix (legacy MonitorBankMatrix + monitorMatrixStyles.ts, copa-preprod 61df4191) ── */
.mon-wrap { position: relative; flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; padding: 0 8px 12px; background: var(--bg-primary); }
.mon-grid { display: grid; gap: 0; height: 100%; grid-auto-rows: minmax(108px, 1fr); grid-template-rows: auto; min-width: 1168px; background: var(--bg-primary); }
.mon-grid > .mon-corner, .mon-grid > .mon-bank { height: auto; }
.mon-corner { position: sticky; top: 0; left: 0; z-index: 4; display: flex; align-items: flex-end; padding: 5px 8px 4px 6px; border-right: 1px solid var(--border-primary); border-bottom: 1px solid var(--border-primary); background: var(--bg-primary); font-size: 11px; line-height: 16.5px; font-weight: 700; letter-spacing: 0.025em; text-transform: uppercase; color: var(--text-secondary); }
.mon-bank { position: sticky; top: 0; z-index: 3; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; gap: 2px; padding: 5px 6px 4px; text-align: center; border-bottom: 1px solid var(--border-primary); background: var(--bg-primary); }
.mon-bank.now { border-bottom: 2px solid var(--accent-success); background: linear-gradient(to bottom, color-mix(in srgb, var(--accent-success) 12%, transparent), transparent), var(--bg-primary); }
.mon-bank.past { opacity: 0.45; }
.mon-bank-name { font-size: 11px; line-height: 1; font-weight: 600; color: var(--text-tertiary); }
.mon-bank.now .mon-bank-name { color: var(--accent-success); }
.mon-bank-time { display: flex; align-items: baseline; column-gap: 4px; font-family: var(--desk-mono); font-size: 10px; line-height: 1; font-variant-numeric: tabular-nums; color: var(--text-tertiary); }
.mon-bank.now .mon-bank-time { font-weight: 700; color: var(--accent-success); }
.mon-past { font-family: var(--desk-font); font-size: 9px; font-weight: 700; letter-spacing: 0.025em; text-transform: uppercase; color: var(--text-disabled); }

.mon-row-head { position: sticky; left: 0; z-index: 2; display: flex; height: 100%; flex-direction: column; justify-content: center; gap: 2px; border-right: 1px solid var(--border-primary); border-bottom: 1px solid var(--border-primary); background: var(--bg-primary); }
.mon-row-btn { display: flex; flex-direction: column; justify-content: center; gap: 4px; padding: 12px 10px; text-align: left; }
.mon-row-title { display: flex; align-items: center; gap: 8px; }
.mon-icon { display: grid; place-items: center; flex-shrink: 0; width: 26px; height: 26px; border-radius: 8px; color: #fff; }
/* legacy MonitorRiskIcon RISK_ICON_BG — fixed in both themes */
.mon-icon.checkin { background: #3b82f6; }
.mon-icon.uncrewed { background: #a855f7; }
.mon-icon.connection { background: #0ea5e9; }
.mon-icon.delayed { background: #ef4444; }
.mon-icon.ftl { background: #f59e0b; }
.mon-row-label { min-width: 0; font-size: 12px; line-height: 1.2; font-weight: 700; letter-spacing: -0.025em; text-wrap: balance; color: var(--text-primary); }
.mon-row-caption { font-size: 10px; line-height: 1.25; color: var(--text-tertiary); }
.mon-row-caption.warn { color: var(--accent-warning); }
.mon-unbanked { padding: 0 10px 4px; border: 0; background: transparent; font-size: 10px; font-weight: 500; text-align: left; color: var(--accent-warning); cursor: pointer; }
.mon-unbanked:hover { text-decoration: underline; }
.mon-row-msg { display: flex; align-items: center; padding: 12px; border-bottom: 1px solid var(--border-primary); font-size: 12px; color: var(--text-tertiary); }

.mon-cell { box-sizing: border-box; display: flex; flex-direction: row; min-height: 108px; height: 100%; width: 100%; overflow: hidden; padding: 6px; border-right: 1px solid var(--border-primary); border-bottom: 1px solid var(--border-primary); }
.mon-cell.now { background: color-mix(in srgb, var(--accent-success) 4%, transparent); }
.mon-cell.past { opacity: 0.45; }
.mon-cell.loading { flex-direction: column; justify-content: flex-start; gap: 8px; padding: 8px 6px; }
.mon-skel { display: inline-block; width: 64px; height: 32px; border-radius: 8px; background: var(--border-primary); animation: mon-pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
.mon-skel.wide { width: 80px; }
@keyframes mon-pulse { 50% { opacity: 0.5; } }
@media (prefers-reduced-motion: reduce) { .mon-skel { animation: none; } }
.mon-counts { display: flex; flex-shrink: 0; width: 25%; height: 100%; flex-direction: column; align-items: center; justify-content: center; gap: 2px; padding-right: 4px; font-family: var(--desk-mono); font-size: 28px; line-height: 1; font-weight: 700; font-variant-numeric: tabular-nums; }
.mon-count { padding: 2px 6px; border: 0; border-radius: 6px; background: transparent; font: inherit; cursor: pointer; }
.mon-count:hover { background: var(--surface-hover); }
.mon-count.crit { color: var(--accent-error); }
.mon-count.warn { color: var(--accent-warning); }
.mon-count.unknown { color: var(--text-tertiary); }
.mon-chips { display: flex; flex: 1; width: 75%; min-width: 0; height: 100%; min-height: 0; align-items: center; justify-content: flex-start; overflow: hidden; }
.mon-chip-list { display: flex; width: 100%; max-height: 100%; flex-flow: row wrap; align-content: flex-start; align-items: center; justify-content: flex-start; gap: 5px; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: none; }
.mon-chip-list::-webkit-scrollbar { display: none; }
.mon-chip { display: flex; flex-flow: row wrap; align-items: baseline; column-gap: 6px; row-gap: 2px; width: fit-content; max-width: 100%; flex-shrink: 0; overflow: hidden; padding: 5px 7px; border-radius: 8px; font-family: var(--desk-mono); font-size: 11px; line-height: 1.25; font-weight: 600; text-align: left; cursor: pointer; }
.mon-chip.crit { background: color-mix(in srgb, var(--accent-error) 16%, transparent); color: var(--accent-error); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent-error) 35%, transparent); }
.mon-chip.warn { background: color-mix(in srgb, var(--accent-warning) 14%, transparent); color: var(--accent-warning); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent-warning) 35%, transparent); }
.mon-chip.stacked { flex-direction: column; align-items: flex-start; }
.mon-chip.stacked .mon-chip-primary { white-space: nowrap; } /* legacy clips a long crew name inside the chip rather than wrapping it */
.mon-chip-meta { display: flex; align-items: baseline; column-gap: 4px; white-space: nowrap; font-family: var(--desk-font); font-size: 10px; line-height: 1.25; font-weight: 500; color: var(--text-secondary); }
.mon-chip-hl { font-weight: 600; }
.mon-chip.crit .mon-chip-hl { color: var(--accent-error); }
.mon-chip.warn .mon-chip-hl { color: var(--accent-warning); }
.mon-badge { display: inline-flex; padding: 1px 4px; border: 0; border-radius: 4px; background: transparent; font: inherit; font-size: 10px; color: inherit; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent-error) 45%, transparent); }
button.mon-badge { cursor: pointer; }
button.mon-badge:hover { background: color-mix(in srgb, var(--accent-error) 18%, transparent); }


/* ── Controller desk D4a — the Console tab (legacy UnifiedConsole, tasks-list/*, OpsKpiCard/KpiChips, KpiDetailPanel,
 *    KpiBankTabsFilter, KpiMonitorScopeBanner; copa-preprod 4f494629). Tailwind palette values are legacy's own. ── */
.con-layout { display: flex; flex: 1; min-height: 0; overflow: hidden; }
.con-sidebar { box-sizing: border-box; display: flex; flex-direction: column; width: 20%; min-width: 180px; max-width: 280px; flex-shrink: 0; border-right: 1px solid var(--border-primary); background: var(--surface-card); }
.con-main { display: flex; flex: 1; min-width: 0; flex-direction: column; overflow-y: auto; border-right: 1px solid var(--border-primary); background: var(--bg-primary); }

/* task sidebar */
.con-tasks { display: flex; height: 100%; flex-direction: column; overflow: hidden; color: var(--text-primary); }
.con-tabs { display: flex; height: 44px; flex-shrink: 0; align-items: center; justify-content: space-between; gap: 6px; padding: 0 12px; border-bottom: 1px solid var(--border-primary); }
.con-tabs-group { display: flex; align-items: center; gap: 6px; }
.con-tab { display: flex; align-items: center; gap: 4px; padding: 4px 8px; border: 0; border-radius: 6px; background: transparent; font-size: 11px; line-height: 1.4286; font-weight: 500; color: var(--text-secondary); cursor: pointer; }
.con-tab:hover { background: var(--surface-hover); color: var(--text-primary); }
.con-tab-count { padding: 0 4px; border-radius: 9999px; font-size: 10px; line-height: 1.4286; font-weight: 600; }
.con-tab.review.active { background: rgba(245, 158, 11, 0.15); color: #b45309; }
.con-tab.review .con-tab-count { background: rgba(245, 158, 11, 0.25); color: #b45309; }
.con-tab.done.active { background: rgba(16, 185, 129, 0.15); color: #047857; }
.con-tab.done .con-tab-count { background: rgba(16, 185, 129, 0.25); color: #047857; }
html:not([data-theme="light"]) .con-tab.review.active, html:not([data-theme="light"]) .con-tab.review .con-tab-count { color: #fcd34d; }
html:not([data-theme="light"]) .con-tab.done.active, html:not([data-theme="light"]) .con-tab.done .con-tab-count { color: #6ee7b7; }
.con-icon-btn { display: inline-flex; padding: 6px; border: 0; border-radius: 6px; background: transparent; color: var(--text-tertiary); cursor: pointer; }
.con-icon-btn:hover { background: var(--surface-hover); }
.con-icon-btn:disabled { opacity: 0.5; }
.con-icon-btn.spinning svg, .con-kpi-refresh.spinning svg { animation: dc-spin 1s linear infinite; }
.con-search { position: relative; flex-shrink: 0; padding: 8px 12px; border-bottom: 1px solid var(--border-primary); }
.con-search-icon { position: absolute; top: 50%; left: 20px; display: inline-flex; transform: translateY(-50%); color: var(--text-tertiary); pointer-events: none; }
.con-search-input { box-sizing: border-box; width: 100%; padding: 6px 28px; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--surface-card); font-family: inherit; font-size: 11px; line-height: 1.4286; color: var(--text-primary); outline: none; -webkit-appearance: none; appearance: none; }
.con-search-input::placeholder { color: var(--text-tertiary); }
.con-search-input::-webkit-search-cancel-button { display: none; }
.con-search-input:focus { border-color: color-mix(in srgb, var(--accent-primary) 50%, transparent); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-primary) 30%, transparent); }
.con-search-clear { position: absolute; top: 50%; right: 16px; display: inline-flex; padding: 4px; border: 0; border-radius: 4px; background: transparent; color: var(--text-tertiary); transform: translateY(-50%); cursor: pointer; }
.con-list { display: flex; min-height: 0; flex: 1; flex-direction: column; gap: 12px; overflow: auto; padding: 12px; }
.con-empty { margin: 0; padding: 8px 0; font-size: 11px; font-style: italic; color: var(--text-tertiary); }
.con-list > .con-empty { padding: 32px 0; text-align: center; font-style: normal; }
.con-cat-head { display: flex; width: 100%; align-items: center; justify-content: space-between; gap: 8px; padding: 6px 8px; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--surface-hover); color: var(--text-primary); cursor: pointer; }
.con-cat-head:hover { background: var(--surface-active); }
