platform/canvas-ui/styles.css:1025:.lp-board { display: flex; flex-direction: column; gap: 12px; padding: 8px 4px 24px; }
platform/canvas-ui/styles.css:1037:.lp-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 12px; }
platform/canvas-ui/styles.css:1066:.lp-status { width: 220px; flex: none; position: sticky; top: 8px; display: flex; flex-direction: column; gap: 8px; }
platform/canvas-ui/styles.css:1098:.np-bank { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; text-align: left; padding: 10px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); color: var(--text-primary); font-family: inherit; cursor: pointer; }
platform/canvas-ui/styles.css:1106:.np-compose { display: flex; flex-direction: column; gap: 12px; }
platform/canvas-ui/styles.css:1108:.np-field { display: flex; flex-direction: column; gap: 6px; font-size: 11px; letter-spacing: 0.04em; color: var(--text-tertiary); }

/* @dcortex/canvas-ui — D12 component styles (rearch/06; the legacy dCortex Console is the
 * pixel source of truth — apps/canvas/design/legacy-console-reference.html). ONE styling
 * system for the whole console: the chrome (header/rail/review/toolbar), the KPI grid, the
 * detail panel, the timeline. Consumes tokens.css — zero hardcoded colors except the brand
 * logo gradient, which 06 pins. Every screen that composes these components inherits the
 * legacy look; there is no second/per-screen stylesheet. */

/* ---- Shell (06 §layout) ---- */
.shell-root { display: flex; flex-direction: column; height: 100vh; overflow: hidden; }
.shell-header {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 0 18px; height: 62px; border-bottom: 1px solid var(--border-primary); background: var(--bg-elevated); flex: none;
}
.shell-brand { display: flex; align-items: center; gap: 11px; }
.shell-logo {
  width: 34px; height: 34px; border-radius: 9px; flex: none;
  background: linear-gradient(135deg, #101828, #1e3a8a); /* the brand tile, the console navy in both themes */
  display: grid; place-items: center; color: #3b82f6; box-shadow: var(--shadow-sm);
}
.shell-logo svg { width: 20px; height: 20px; }
/* tenant/airline logo tile (header brands to the operating customer) */
.shell-logo-img { width: 34px; height: 34px; border-radius: 9px; flex: none; object-fit: cover; box-shadow: var(--shadow-sm); }
.shell-brand b { font-size: 15px; font-weight: 700; letter-spacing: -0.01em; line-height: 1.1; }
.shell-brand small { display: block; font-size: 11px; color: var(--text-tertiary); }
.shell-controls { display: flex; align-items: center; gap: 8px; }
.shell-body { display: flex; flex: 1; min-height: 0; }
.shell-rail {
  width: 55px; flex: none; display: flex; flex-direction: column; align-items: center;
  gap: 6px; padding: 12px 0; border-right: 1px solid var(--border-primary); background: var(--bg-secondary);
}
.rail-item {
  width: 40px; height: 40px; display: grid; place-items: center;
  border: none; border-radius: var(--radius-lg); background: transparent;
  color: var(--text-tertiary); cursor: pointer; text-decoration: none;
}
.rail-item:hover { background: var(--surface-hover); color: var(--text-primary); }
.rail-item.active { background: var(--accent-primary); color: var(--text-on-accent); }
.rail-item svg { width: 20px; height: 20px; }
.shell-sidebar {
  width: 280px; flex: none; border-right: 1px solid var(--border-primary); background: var(--bg-primary);
  display: flex; flex-direction: column; overflow: hidden; transition: width 0.2s ease, opacity 0.15s;
}
.shell-sidebar.collapsed { width: 0; opacity: 0; border-right: 0; pointer-events: none; }
/* main is the scroll container (back-compat: every screen's content scrolls here); a
 * console-toolbar sticks to the top while the content below it scrolls. */
.shell-main { flex: 1; min-width: 0; overflow: auto; display: flex; flex-direction: column; }
.shell-content { padding: 18px; }

/* ---- Console header chrome (ConsoleHeader) ---- */
/* Legacy header controls: uniform 32px, radius-lg, 1px border; alert red-tinted with a triangle-alert
   icon + count badge; EN/ES a segmented pill (blue active); theme a bordered sun/moon button. */
.bell {
  position: relative; width: 32px; height: 32px; box-sizing: border-box; border-radius: var(--radius-lg); display: grid; place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent-error), transparent 65%);
  background: color-mix(in srgb, var(--accent-error), transparent 90%); color: var(--accent-error); cursor: pointer;
}
.bell:hover { background: color-mix(in srgb, var(--accent-error), transparent 84%); }
.bell .ct {
  position: absolute; top: -6px; right: -6px; min-width: 18px; height: 18px; border-radius: 999px; background: var(--accent-error);
  color: #fff; font-size: 10px; font-weight: 700; display: grid; place-items: center; padding: 0 4px;
}
.lang { display: inline-flex; gap: 2px; padding: 2px; height: 32px; box-sizing: border-box; align-items: center; border: 1px solid var(--border-primary); border-radius: var(--radius-lg); background: var(--bg-secondary); }
.lang button { font: inherit; font-size: 11px; font-weight: 600; height: 24px; display: inline-flex; align-items: center; padding: 0 12px; border: 0; border-radius: var(--radius-md); cursor: pointer; background: transparent; color: var(--text-secondary); }
.lang button:hover { color: var(--text-primary); }
.lang button.on { background: var(--accent-primary); color: var(--text-on-accent); }
.zone-select { font: inherit; font-size: 11px; font-weight: 600; height: 32px; max-width: 190px; box-sizing: border-box; padding: 0 8px; border: 1px solid var(--border-primary); border-radius: var(--radius-lg); background: var(--bg-secondary); color: var(--text-secondary); cursor: pointer; }
.zone-select:hover { color: var(--text-primary); }
.user {
  display: inline-flex; align-items: center; gap: 8px; height: 32px; border: 1px solid var(--border-primary); border-radius: var(--radius-lg);
  padding: 0 12px; font-size: 12px; color: var(--text-secondary); cursor: pointer; background: var(--bg-secondary);
}
.user .user-avatar { flex: none; color: var(--text-tertiary); }
.user .user-name { max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.user .user-caret { flex: none; color: var(--text-tertiary); }

/* ---- User dropdown menu (header user → Logout) ---- */
.usermenu { position: relative; display: inline-flex; }
.usermenu .user { font-family: inherit; }
.usermenu .user:hover { background: var(--surface-hover); color: var(--text-primary); }
.usermenu-scrim { position: fixed; inset: 0; z-index: 40; border: 0; padding: 0; margin: 0; background: transparent; cursor: default; }
.usermenu-pop {
  position: absolute; right: 0; top: calc(100% + 6px); z-index: 41; min-width: 168px; padding: 4px;
  display: flex; flex-direction: column; background: var(--surface-card); border: 1px solid var(--border-primary);
  border-radius: var(--radius-lg); box-shadow: var(--shadow-md);
}
.usermenu-item {
  font: inherit; font-size: 12.5px; text-align: left; padding: 8px 12px; border: 0; border-radius: var(--radius-md);
  background: transparent; color: var(--text-secondary); cursor: pointer;
}
.usermenu-item:hover { background: var(--surface-hover); color: var(--text-primary); }

/* ---- Icon button (06 §buttons) ---- */
.iconbtn {
  width: 32px; height: 32px; display: inline-grid; place-items: center;
  background: var(--bg-secondary); border: 1px solid var(--border-primary);
  border-radius: var(--radius-lg); color: var(--text-secondary); cursor: pointer; font-size: 15px;
}
.iconbtn:hover { background: var(--surface-hover); color: var(--text-primary); }

/* ---- Review sidebar (ReviewSidebar) — same height + tab styling as the toolbar so the two panel
   headers align exactly (legacy: both tab rows share a baseline). ---- */
.review-head { display: flex; align-items: center; gap: 6px; padding: 0 12px; height: 48px; border-bottom: 1px solid var(--border-primary); flex: none; }
.review-tab {
  font-size: 11px; font-weight: 500; border-radius: var(--radius-md); padding: 4px 8px; border: 0;
  background: transparent; color: var(--text-secondary); cursor: pointer; display: inline-flex; align-items: center; gap: 5px;
}
/* Active-toggle tabs: the SELECTED tab gets a tinted rounded chip — Review → amber, Done → green — and
   the other resets to gray. Inactive tabs hover to a surface tint. */
.review-tab:not(.on):hover { background: var(--surface-hover); color: var(--text-primary); }
.review-tab.on:first-child {
  background: color-mix(in srgb, var(--accent-warning), transparent 85%); color: var(--cell-amber-tx);
}
.review-tab.on:nth-child(2) {
  background: color-mix(in srgb, var(--accent-success), transparent 85%); color: var(--accent-success);
}
.review-cnt {
  min-width: 16px; height: 15px; border-radius: 999px; display: inline-grid; place-items: center; font-size: 10px; font-weight: 600; padding: 0 4px;
  background: var(--surface-hover); color: var(--text-tertiary);
}
.review-tab.on:first-child .review-cnt { background: color-mix(in srgb, var(--accent-warning), transparent 75%); color: var(--cell-amber-tx); }
.review-tab.on:nth-child(2) .review-cnt { background: color-mix(in srgb, var(--accent-success), transparent 75%); color: var(--accent-success); }
/* review-header icon controls (refresh + close) — legacy: ~26px, 6px pad, radius-md; first one right-aligned. */
.review-tab + .review-icon { margin-left: auto; }
.review-icon { width: 26px; height: 26px; display: inline-grid; place-items: center; border-radius: var(--radius-md); border: 0; background: transparent; cursor: pointer; }
.review-refresh { color: var(--text-primary); }
.review-close { color: var(--text-tertiary); }
.review-icon:hover { background: var(--surface-hover); color: var(--text-primary); }
.review-body { overflow: auto; padding: 12px 14px; display: flex; flex-direction: column; gap: 16px; }
.review-badge {
  display: inline-flex; align-items: center; gap: 5px; border-radius: var(--radius-md); padding: 3px 9px; font-size: 11px; font-weight: 600;
  background: color-mix(in srgb, var(--accent-warning), transparent 84%); color: var(--accent-warning);
}

/* ---- Console toolbar (Toolbar / view tabs + date chips) ---- */
.console-toolbar { position: sticky; top: 0; z-index: 3; display: flex; align-items: center; gap: 14px; padding: 0 18px; min-height: 48px; border-bottom: 1px solid var(--border-primary); background: var(--bg-primary); flex-wrap: wrap; }
.toolbar-dates { display: flex; gap: 6px; align-items: center; flex-wrap: wrap; }
/* Match legacy console toolbar: 11px chips, tighter padding; inactive date chips carry a surface tint. */
.console-toolbar .chip { font-size: 11px; padding: 4px 10px; gap: 5px; }
.toolbar-dates .chip:not(.active) { background: var(--bg-secondary); }
.chip-icon { display: inline-flex; align-items: center; }
.chip-icon svg { width: 13px; height: 13px; display: block; }
.toolbar-spacer { flex: 1; }

/* ---- Segmented chips (06 §toolbar) ---- */
/* Legacy view-switcher = a JOINED segmented group (tabs touch; only the group ends are rounded). */
.segmented { display: inline-flex; gap: 0; padding: 3px; background: var(--bg-secondary); border: 1px solid var(--border-primary); border-radius: var(--radius-lg); }
.segmented .chip { border-radius: 0; }
.segmented .chip:first-child { border-radius: var(--radius-md) 0 0 var(--radius-md); }
.segmented .chip:last-child { border-radius: 0 var(--radius-md) var(--radius-md) 0; }
.chip-count {
  margin-left: 6px; min-width: 18px; height: 18px; border-radius: 999px; display: inline-grid; place-items: center; padding: 0 5px; font-size: 10px; font-weight: 700;
  background: color-mix(in srgb, var(--text-tertiary), transparent 80%);
}

/* ---- KPI grid + card (06 §components) ---- */
.kpi-grid { display: grid; gap: 12px; grid-template-columns: repeat(8, minmax(0, 1fr)); }
@media (max-width: 1500px) { .kpi-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
@media (max-width: 820px) { .kpi-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
/* Dashboard two-panel split (legacy SupervisorDashboard): a FIXED top KPI strip + a detail panel below
   that scrolls independently. .dash-split fills the shell-main column; only .dash-detail scrolls. */
.dash-split { flex: 1; min-height: 0; display: flex; flex-direction: column; padding: 18px; gap: 12px; }
.dash-strip { flex: none; }
.dash-detail { flex: 1; min-height: 0; overflow-y: auto; border-top: 1px solid var(--border-primary); }
.dash-detail-empty { display: flex; align-items: center; justify-content: center; height: 100%; min-height: 160px; color: var(--text-tertiary); font-size: 13px; text-align: center; padding: 24px; }
/* Inline task list for the task-derived KPI details (uncrewed / absences). */
.dash-task-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.dash-task-item { width: 100%; text-align: left; background: var(--surface-card); border: 1px solid var(--border-primary); border-radius: var(--radius-md); padding: 10px 12px; font-size: 13px; color: var(--text-primary); cursor: pointer; transition: 0.12s; }
.dash-task-item:hover { background: var(--surface-hover); border-color: var(--border-secondary); }
/* Legacy console KPI band: one horizontal row that scrolls sideways on narrow widths instead of wrapping.
   The doubled selector outranks the .kpi-grid @media rules above, so it stays single-row at every width. */
.kpi-strip { overflow-x: auto; padding-bottom: 2px; }
.kpi-grid.kpi-grid--strip { grid-template-columns: none; grid-auto-flow: column; grid-auto-columns: minmax(150px, 1fr); gap: 8px; }
.kpi-card {
  display: flex; flex-direction: column; min-height: 152px;
  background: var(--surface-card); border: 1px solid var(--border-primary);
  border-radius: var(--radius-xl); padding: 13px 13px 12px; cursor: pointer; box-shadow: var(--shadow-sm); transition: 0.15s;
}
.kpi-card:hover { border-color: var(--border-secondary); box-shadow: var(--shadow-md); }
.kpi-card.selected {
  border-color: var(--accent-primary); box-shadow: 0 0 0 1px var(--accent-primary);
  background: color-mix(in srgb, var(--accent-primary), transparent 93%);
}
.kpi-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 6px; }
.kpi-title { flex: 1; min-width: 0; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text-tertiary); line-height: 1.35; }
/* Legacy card chrome: top-right refresh control (rendered only when the card supplies onRefresh). */
.kpi-refresh {
  flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px;
  padding: 0; border: 1px solid var(--border-primary); border-radius: var(--radius-md); background: transparent;
  color: var(--text-tertiary); cursor: pointer; transition: 0.15s;
}
.kpi-refresh:hover { background: var(--surface-hover); color: var(--text-primary); }
.kpi-refresh:disabled { cursor: not-allowed; opacity: 0.5; }
.kpi-refresh.spinning svg { animation: kpi-spin 0.8s linear infinite; }
@keyframes kpi-spin { to { transform: rotate(360deg); } }
/* Dashboard strip only: compact card height + hover tint to match legacy's KpiStrip proportions. */
.kpi-grid--strip .kpi-card { min-height: 108px; padding: 8px; }
.kpi-strip .kpi-card:hover { background: var(--surface-hover); }
.kpi-value { font-size: 32px; font-weight: 700; letter-spacing: -0.02em; margin: 6px 0 auto; font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.kpi-value.red { color: var(--accent-error); }
.kpi-value.green { color: var(--accent-success); }
.kpi-value.amber { color: var(--accent-warning); }
.kpi-value.teal { color: var(--accent-teal); }
.kpi-pills { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 8px; }
/* Legacy KpiSplitFooter: two stacked columns pushed to the card edges (left tags | right tags). */
.kpi-pills.split { flex-wrap: nowrap; justify-content: space-between; align-items: flex-end; gap: 6px; }
.kpi-pills-group { display: flex; flex-direction: column; gap: 4px; align-items: flex-start; min-width: 0; }
/* right column keeps its natural single-line width (legacy `shrink-0`) with single-line chips; the left
   column's chips hug their wrapped text (cap forces "Flight Attendants" to 2 lines, shorter chips stay 1). */
.kpi-pills-group.right { align-items: flex-end; text-align: right; flex-shrink: 0; }
.kpi-pills-group.right .pill { white-space: nowrap; }
.kpi-grid--strip .kpi-pills-group:not(.right) .pill { max-width: 52px; }
/* Dashboard strip cards match legacy KpiStrip typography: 20px value, brighter (primary) title, 9px
   rounded-SQUARE chips (not pills), and a consistent title→value gap via a min-height title row. */
.kpi-grid--strip .kpi-head { min-height: 30px; }
.kpi-grid--strip .kpi-value { font-size: 20px; line-height: 1; margin: 7px 0 auto; }
.kpi-grid--strip .kpi-title { color: var(--text-primary); }
.kpi-grid--strip .pill { font-size: 9px; padding: 2px 6px; line-height: 1.25; border-radius: 4px; }

/* ---- Detail panel (DetailPanel) ---- */
.panel { margin-top: 18px; background: var(--surface-card); border: 1px solid var(--border-primary); border-radius: var(--radius-xl); padding: 16px 18px; box-shadow: var(--shadow-sm); }
.panel .panel-head { display: flex; align-items: center; gap: 8px; font-size: 14px; font-weight: 600; color: var(--text-primary); }
.panel .panel-empty { margin-top: 8px; font-size: 13px; color: var(--text-tertiary); }

/* ---- Timeline Gantt (06 §components) ---- */
.gantt { overflow-x: auto; }
.gantt-axis { position: relative; height: 28px; margin-left: var(--labelW); border-bottom: 1px solid var(--border-primary); background: var(--bg-primary); }
.gantt-tz { position: sticky; left: 0; font-size: 10px; color: var(--text-tertiary); padding-right: 8px; }
.gantt-tick { position: absolute; top: 6px; transform: translateX(-50%); font-size: 10px; color: var(--text-tertiary); }
.gantt-row { display: flex; align-items: center; height: var(--rowH); }
.gantt-label { width: var(--labelW); flex: none; position: sticky; left: 0; font-size: 11px; color: var(--text-secondary); background: var(--bg-primary); }
.gantt-track { position: relative; height: 100%; background-image: repeating-linear-gradient(to right, var(--grid-line) 0 1px, transparent 1px var(--hourW)); }
.gantt-bar { position: absolute; top: 4px; bottom: 4px; border-radius: 5px; display: inline-flex; align-items: center; padding: 0 6px; font-size: 10px; white-space: nowrap; overflow: hidden; }
.gantt-bar:hover { filter: brightness(1.15); }
.gantt-bar.sky { background: var(--sky-bg); border: 1px solid var(--sky-bd); color: var(--sky-tx); }
.gantt-bar.green { background: var(--emer-bg); border: 1px solid var(--emer-bd); color: var(--emer-tx); }
.gantt-bar.red { background: var(--red-bg); border: 1px solid var(--red-bd); color: var(--red-tx); }
.gantt-tag { position: absolute; top: 50%; transform: translateY(-50%); border-radius: 999px; padding: 1px 8px; font-size: 10px; font-weight: 600; white-space: nowrap; }
.gantt-tag.early { background: var(--tag-early-bg); color: var(--tag-early-tx); }
.gantt-tag.delay { background: var(--tag-delay-bg); color: var(--tag-delay-tx); }
.gantt-task-dot { position: absolute; top: 2px; width: 5px; height: 5px; border-radius: 50%; background: var(--accent-error); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent-error), transparent 75%); }

/* shared spinner (RefreshButton) */
@keyframes dc-spin { to { transform: rotate(360deg); } }

/* ───────────────────────── Controller desk (D2) ─────────────────────────
 * Matched to legacy /desk (copa-preprod 61df4191; knowledge-base/features/controller-desk.md §D2 visual spec).
 * Ruling E: the desk renders in the system font stack, scoped here — the rest of Canvas keeps its fonts.
 * Colours are tokens only; legacy's own hard-coded Tailwind colours (cyan selection) are noted where used. */
.desk-root {
  --desk-font: var(--font-sans);
  --desk-mono: var(--font-mono);
  display: flex; flex-direction: column; height: 100vh; overflow: hidden;
  background: var(--bg-primary); color: var(--text-primary);
  font-family: var(--desk-font); font-size: 16px; line-height: 1.5;
  -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale;
}
.desk-root button { font-family: inherit; }

/* header — navbar.tsx on /desk: sticky, 95% elevated fill, compact 3-column grid */
.desk-header {
  position: sticky; top: 0; z-index: 50; flex-shrink: 0;
  border-bottom: 1px solid var(--border-primary);
  background: color-mix(in srgb, var(--bg-elevated) 95%, transparent);
  backdrop-filter: blur(4px); box-shadow: var(--shadow-sm);
}
.desk-header-grid { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 8px; padding: 4px 16px; }
@media (min-width: 768px) { .desk-header-grid { padding: 4px 24px; } }
.desk-brand { display: flex; align-items: center; gap: 8px; min-width: 0; }
.desk-logo { display: flex; align-items: center; justify-content: center; overflow: hidden; width: 24px; height: 24px; border-radius: 8px; background: color-mix(in srgb, var(--accent-primary) 10%, transparent); color: var(--accent-primary); }
.desk-logo svg { width: 16px; height: 16px; }
.desk-logo img { width: 100%; height: 100%; object-fit: contain; }
.desk-org { font-size: 12px; line-height: 16px; font-weight: 600; letter-spacing: -0.3px; color: var(--text-primary); white-space: nowrap; }
.desk-center { min-width: 0; justify-self: center; display: flex; align-items: center; justify-content: center; gap: 12px; }
.desk-right { display: flex; align-items: center; justify-content: flex-end; gap: 8px; justify-self: end; font-size: 12px; }

/* navControlStyles.ts — segment group, segments, control buttons */
.nav-seg-group { display: inline-flex; align-items: center; height: 28px; box-sizing: border-box; padding: 1px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); }
.nav-seg-slot { display: inline-flex; align-items: center; }
.nav-seg-divider { display: inline-block; width: 1px; height: 16px; margin: 0 2px; background: var(--border-primary); }
.nav-seg { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 10px; border: 0; border-radius: 6px; background: transparent; color: var(--text-secondary); font-size: 11px; line-height: 16.5px; font-weight: 600; white-space: nowrap; cursor: pointer; transition: background-color 0.15s, color 0.15s; }
.nav-seg:hover { background: var(--surface-hover); color: var(--text-primary); }
.nav-seg.on, .nav-seg.on:hover { background: var(--accent-primary); color: var(--text-on-accent); box-shadow: var(--shadow-sm); }
.nav-seg svg { flex-shrink: 0; }
.nav-seg-group.uppercase .nav-seg { text-transform: uppercase; letter-spacing: 0.025em; }
.nav-ctl { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 28px; box-sizing: border-box; padding: 0 10px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); color: var(--text-primary); font-size: 11px; font-weight: 600; white-space: nowrap; cursor: pointer; transition: background-color 0.15s, color 0.15s; }
