.con-task { padding: 8px 10px; border: 1px solid var(--border-secondary); border-radius: 8px; background: var(--surface-card); cursor: pointer; }
.con-task:hover { background: var(--surface-hover); }
.con-task.selected { border-color: var(--accent-primary); background: color-mix(in srgb, var(--accent-primary) 10%, transparent); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-primary) 40%, transparent); }
.con-task-title { display: -webkit-box; margin: 0; overflow: hidden; font-size: 14px; line-height: 20px; font-weight: 500; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.con-task-row { display: flex; margin-top: 4px; align-items: center; justify-content: space-between; gap: 6px; }
