.con-status { display: flex; margin-left: auto; flex-shrink: 0; align-items: center; padding: 2px 6px; border-radius: 9999px; font-size: 10px; line-height: 1.4286; font-weight: 500; }
.con-status.todo { background: #e0f2fe; color: #075985; }
.con-status.review { background: #fef3c7; color: #b45309; }
