.cand-meta { margin-top: 2px; font-size: 11px; line-height: 1.4286; color: var(--text-tertiary); }
.cand-note { margin-top: 2px; font-size: 10px; line-height: 1.4286; color: var(--accent-warning); }
.cand-pager { position: sticky; top: 0; z-index: 2; display: flex; align-items: center; justify-content: center; gap: 12px; padding: 8px 12px; border-top: 1px solid color-mix(in srgb, var(--accent-primary) 30%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--accent-primary) 30%, transparent); background: color-mix(in srgb, var(--accent-primary) 10%, transparent); font-size: 11px; color: var(--text-primary); }
.cand-pager-btn { padding: 2px 8px; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--surface-card); font-family: inherit; font-size: 11px; font-weight: 600; color: var(--text-primary); cursor: pointer; }
.cand-pager-btn:disabled { cursor: not-allowed; opacity: 0.5; }
.cand-pager-range { font-variant-numeric: tabular-nums; }

/* footer actions + forms */
.case-act { padding: 12px 16px; border: 1px solid var(--border-primary); border-radius: 12px; background: var(--surface-card); font-family: inherit; font-size: 14px; line-height: 1.4286; font-weight: 500; color: var(--text-primary); cursor: pointer; }
.case-act:disabled { cursor: not-allowed; opacity: 0.5; }
.case-act.accept { border-color: color-mix(in srgb, var(--accent-success) 45%, transparent); background: color-mix(in srgb, var(--accent-success) 12%, transparent); color: var(--accent-success); }
.case-act.override { border-color: color-mix(in srgb, var(--accent-error) 45%, transparent); background: color-mix(in srgb, var(--accent-error) 12%, transparent); color: var(--accent-error); }
.case-form { display: flex; width: 100%; flex-wrap: wrap; align-items: center; gap: 8px; }
.case-form-input { box-sizing: border-box; min-width: 0; flex: 1; padding: 8px 10px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-input); font-family: inherit; font-size: 12px; color: var(--text-primary); }
