.cand-detail { display: flex; flex-direction: column; gap: 10px; padding: 10px 12px 12px 40px; border-top: 1px solid var(--border-primary); background: var(--bg-secondary); }
.cand-detail-block { display: flex; flex-direction: column; gap: 4px; }
.cand-legality { display: inline-block; width: fit-content; padding: 1px 6px; border-radius: 4px; background: var(--surface-hover); font-size: 11px; line-height: 1.4286; font-weight: 600; color: var(--text-secondary); }
.cand-legality.legal { background: color-mix(in srgb, var(--accent-success) 15%, transparent); color: var(--accent-success); }
.cand-legality.illegal { background: color-mix(in srgb, var(--accent-error) 15%, transparent); color: var(--accent-error); }
.cand-unavailable { font-size: 11px; line-height: 1.4286; color: var(--text-tertiary); }
.case-strip { display: grid; grid-template-columns: repeat(auto-fill, minmax(84px, 1fr)); gap: 4px; }
.case-strip-day { display: flex; flex-direction: column; gap: 1px; padding: 4px 6px; border-radius: 4px; background: var(--surface-hover); font-size: 11px; line-height: 1.4286; color: var(--text-secondary); }
